{"command":"python3 - << 'PY'
import subprocess, pty, os, time, fcntl

def repl_session(commands):
    master, slave = pty.openpty()
    proc = subprocess.Popen(["./executable","-r"], stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    time.sleep(0.3)
    fl = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, fl | os.O_NONBLOCK)
    def read_all():
        data=b""
        while True:
            try:
                chunk=os.read(master, 8192)
                if not chunk:
                    break
                data+=chunk
            except BlockingIOError:
                break
            except OSError:
                break
        return data
    out = read_all().decode(errors='ignore')
    print("INIT:", repr(out))
    outputs=[]
    for cmd in commands:
        os.write(master, (cmd+"\n").encode())
        time.sleep(0.4)
        chunk = read_all().decode(errors='ignore')
        print(f"After {cmd!r}: {chunk!r}")
        outputs.append(chunk)
    os.write(master, b":e\n")
    time.sleep(0.3)
    print(read_all().decode(errors='ignore'))
    proc.terminate()
    try:
        os.close(master)
    except:
        pass

