    }
}

#[derive(Debug, Clone)]
enum Atom {
    Literal(String),
    Raw(String),
    Symbol(Symbol, bool), // bool negated
    Range(char, char, bool),
    NotClass(String, bool), // class content string, bool negated? Actually NotClass always negated? But we have both not and positive range. For simplicity, we have Range with negated flag, and NotClass for [^...] where content is bare string.
    Group(GroupKind, Vec<Stmt>),
    VarInv(String),
}

#[derive(Debug, Clone)]
enum GroupKind {
    Match,
    Either,
    Capture(Option<String>),
    Ahead,
    Behind,
    NotAhead,
    NotBehind,
}

#[derive(Debug, Clone)]
enum QuantPrefix {
    Some,
    Any,
    Option,
    Exact(usize),
    Range(usize, usize),
    Over(usize),
}

#[derive(Debug, Clone)]
enum Stmt {
    Simple(Atom), // will be terminated with ; if needed, but we treat as atom that already includes;? For our evaluation, Simple contains atom and will be compiled directly.
    Quantified(QuantPrefix, bool, Atom), // bool is lazy
    VarDecl(String, Vec<Stmt>),
    // For parser, we need to distinguish statement termination, but for evaluation we use same.
}

struct Context {
    vars: HashMap<String, String>, // var name -> compiled regex
}

impl Context {
    fn new() -> Self {
        Context { vars: HashMap::new() }
    }

    fn eval_stmt_list(&mut self, stmts: &[Stmt]) -> Result<String, CompileError> {
        let mut out = String::new();
        for stmt in stmts {
            out.push_str(&self.eval_statement(stmt)?);
        }
        Ok(out)
    }

    fn eval_statement(&mut self, stmt: &Stmt) -> Result<String, CompileError> {
        match stmt {
            Stmt::Simple(atom) => self.eval_atom(atom),
            Stmt::Quantified(prefix, lazy, atom) => {
                // Check if atom is allowed in quantifier
                match atom {
                    Atom::Group(k, _) => match k {
                        GroupKind::Ahead | GroupKind::Behind | GroupKind::NotAhead | GroupKind::NotBehind => {
                            return Err(CompileError {
                                line: 0,
                                col: 0,
                                line_content: String::new(),
                                expected: String::new(),
                                custom_message: Some("Error: unexpected assertion in quantifier".to_string()),
                            });
                        },
                        _ => {}
                    },
                    Atom::VarInv(_) => {
                        return Err(CompileError {
                            line: 0,
                            col: 0,
                            line_content: String::new(),
                            expected: String::new(),
                            custom_message: Some("Error: unexpected variable invocation in quantifier".to_string()),
                        });
                    },
                    _ => {}
                }
                let base = self.eval_atom(atom)?;
                let quant = match prefix {
                    QuantPrefix::Some => "+",
                    QuantPrefix::Any => "*",
                    QuantPrefix::Option => "?",
                    QuantPrefix::Exact(n) => {
                        // We'll format later
                        ""
                    },
                    QuantPrefix::Range(a,b) => "",
                    QuantPrefix::Over(n) => "",
                };
                let result = match prefix {
                    QuantPrefix::Some => format!("{}+", base),
                    QuantPrefix::Any => format!("{}*", base),
                    QuantPrefix::Option => format!("{}?", base),
                    QuantPrefix::Exact(n) => format!("{}{{ {} }}", base, n).replace(" ", ""), // will be fixed
                    QuantPrefix::Range(a,b) => format!("{}{{ {},{} }}", base, a, b).replace(" ", ""),
                    QuantPrefix::Over(n) => format!("{}{{ {},}}", base, n+1).replace(" ", ""),
                };
                // Actually for Exact and Range and Over we need correct formatting without spaces
                let result = match prefix {
                    QuantPrefix::Exact(n) => format!("{}{{{}}}", base, n),
                    QuantPrefix::Range(a,b) => format!("{}{{{},{}}}", base, a, b),
                    QuantPrefix::Over(n) => format!("{}{{{},}}", base, n+1),
                    QuantPrefix::Some => format!("{}+", base),
                    QuantPrefix::Any => format!("{}*", base),
                    QuantPrefix::Option => format!("{}?", base),
                };
                if *lazy {
                    Ok(format!("{}?", result))
                } else {
                    Ok(result)
                }
            },
            Stmt::VarDecl(name, body) => {
                // body is Vec<Stmt>
                let compiled = self.eval_stmt_list(body)?;
                self.vars.insert(name.clone(), compiled);
                Ok(String::new())
            },
        }
    }

