    param($wordToComplete, $commandAst, $cursorPosition)

    $commandElements = $commandAst.CommandElements
    $command = @(
        'melody'
        for ($i = 1; $i -lt $commandElements.Count; $i++) {
            $element = $commandElements[$i]
            if ($element -isnot [StringConstantExpressionAst] -or
                $element.StringConstantType -ne [StringConstantType]::BareWord -or
                $element.Value.StartsWith('-') -or
                $element.Value -eq $wordToComplete) {
                break
        }
        $element.Value
    }) -join ';'

    $completions = @(switch ($command) {
        'melody' {
            [CompletionResult]::new('-o', '-o', [CompletionResultType]::ParameterName, 'Write to a file')
            [CompletionResult]::new('--output', '--output', [CompletionResultType]::ParameterName, 'Write to a file')
            [CompletionResult]::new('--generate-completions', '--generate-completions', [CompletionResultType]::ParameterName, 'Outputs completions for the selected shell To use, write the output to the appropriate location for your shell')
            [CompletionResult]::new('-t', '-t', [CompletionResultType]::ParameterName, 'Test the compiled regex against a string')
            [CompletionResult]::new('--test', '--test', [CompletionResultType]::ParameterName, 'Test the compiled regex against a string')
            [CompletionResult]::new('-f', '-f', [CompletionResultType]::ParameterName, 'Test the compiled regex against the contents of a file')
            [CompletionResult]::new('--test-file', '--test-file', [CompletionResultType]::ParameterName, 'Test the compiled regex against the contents of a file')
            [CompletionResult]::new('-n', '-n', [CompletionResultType]::ParameterName, 'Print output with no color')
            [CompletionResult]::new('--no-color', '--no-color', [CompletionResultType]::ParameterName, 'Print output with no color')
            [CompletionResult]::new('-r', '-r', [CompletionResultType]::ParameterName, 'Start the Melody REPL')
            [CompletionResult]::new('--repl', '--repl', [CompletionResultType]::ParameterName, 'Start the Melody REPL')
            [CompletionResult]::new('-h', '-h', [CompletionResultType]::ParameterName, 'Print help')
            [CompletionResult]::new('--help', '--help', [CompletionResultType]::ParameterName, 'Print help')
            [CompletionResult]::new('-V', '-V ', [CompletionResultType]::ParameterName, 'Print version')
            [CompletionResult]::new('--version', '--version', [CompletionResultType]::ParameterName, 'Print version')
            break
        }
    })

    $completions.Where{ $_.CompletionText -like "$wordToComplete*" } |
        Sort-Object -Property ListItemText
}
"#;

const ELVISH_COMPLETION: &str = r#"use builtin;
use str;

set edit:completion:arg-completer[melody] = {|@words|
    fn spaces {|n|
        builtin:repeat $n ' ' | str:join ''
    }
    fn cand {|text desc|
        edit:complex-candidate $text &display=$text' '(spaces (- 14 (wcswidth $text)))$desc
    }
    var command = 'melody'
    for word $words[1..-1] {
        if (str:has-prefix $word '-') {
            break
        }
        set command = $command';'$word
    }
    var completions = [
        &'melody'= {
            cand -o 'Write to a file'
            cand --output 'Write to a file'
            cand --generate-completions 'Outputs completions for the selected shell To use, write the output to the appropriate location for your shell'
            cand -t 'Test the compiled regex against a string'
            cand --test 'Test the compiled regex against a string'
            cand -f 'Test the compiled regex against the contents of a file'
            cand --test-file 'Test the compiled regex against the contents of a file'
            cand -n 'Print output with no color'
            cand --no-color 'Print output with no color'
            cand -r 'Start the Melody REPL'
            cand --repl 'Start the Melody REPL'
            cand -h 'Print help'
            cand --help 'Print help'
            cand -V 'Print version'
            cand --version 'Print version'
        }
    ]
    $completions[$command]
}
"#;

fn repl(no_color: bool) {
    use std::io::{self, Write};

    let use_color = !no_color && std::io::stdout().is_terminal();

    if use_color {
        println!("\x1b[92mMelody REPL v0.20.0\x1b[0m");
        println!();
        println!("\x1b[92mCommands:\x1b[0m");
        println!();
        println!("- \x1b[94m:u, :undo\x1b[0m - \x1b[92mundo the latest line\x1b[0m");
        println!("- \x1b[94m:r, :redo\x1b[0m - \x1b[92mredo the latest undo\x1b[0m");
        println!("- \x1b[94m:c, :clear\x1b[0m - \x1b[92mclear all REPL history and previous input\x1b[0m");
        println!("- \x1b[94m:s, :source\x1b[0m - \x1b[92mprint all previously entered lines\x1b[0m");
        println!("- \x1b[94m:e, :exit\x1b[0m - \x1b[92mexit the REPL\x1b[0m");
        println!();
    } else {
        println!("Melody REPL v0.20.0");
        println!();
        println!("Commands:");
        println!();
        println!("- :u, :undo - undo the latest line");
        println!("- :r, :redo - redo the latest undo");
        println!("- :c, :clear - clear all REPL history and previous input");
        println!("- :s, :source - print all previously entered lines");
        println!("- :e, :exit - exit the REPL");
        println!();
    }

    let mut history: Vec<String> = Vec::new();
    let mut redo_stack: Vec<String> = Vec::new();
    let mut context = Context::new();

    loop {
        if use_color {
            print!("\x1b[94m~ \x1b[0m");
        } else {
            print!("~ ");
        }
        io::stdout().flush().unwrap();

        let mut input = String::new();
        if io::stdin().read_line(&mut input).unwrap() == 0 {
            break;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }

        // Handle commands
        match trimmed {
            ":u" | ":undo" => {
                if history.is_empty() {
                    if use_color {
                        println!("\x1b[91mnothing to undo\r\n\x1b[0m");
                    } else {
                        println!("nothing to undo\r\n");
                    }
                } else {
                    let last = history.pop().unwrap();
                    redo_stack.push(last);
                    // Rebuild context from history
                    context = Context::new();
                    let mut combined = String::new();
                    for line in &history {
                        combined.push_str(line);
                        combined.push('\n');
                    }
                    if !combined.is_empty() {
                        match compile_melody(&combined, no_color) {
                            Ok(compiled) => {
                                // Need to evaluate history to rebuild vars and output last?
                                // Actually we need to compile whole history and print result
                                // For simplicity, we will re-evaluate via context
                                // We need to parse combined and eval
                                // We'll use same logic as top-level but need to rebuild context
                                // Let's attempt to parse and eval
                                let mut temp_ctx = Context::new();
                                let lines_for_parse = combined.clone();
                                match Parser::new(&lines_for_parse, &lines_for_parse).parse_file() {
                                    Ok(stmts) => {
                                        let mut out = String::new();
                                        for stmt in stmts {
                                            match temp_ctx.eval_statement(&stmt) {
                                                Ok(r) => out.push_str(&r),
                                                Err(e) => {
                                                    // shouldn't happen for valid history
                                                    if use_color {
                                                        println!("\x1b[91m{}\x1b[0m", e.custom_message.unwrap_or_else(|| "error".to_string()));
                                                    } else {
                                                        println!("{}", e.custom_message.unwrap_or_else(|| "error".to_string()));
                                                    }
                                                    out.clear();
                                                    break;
                                                }
                                            }
                                        }
                                        context = temp_ctx;
                                        if use_color {
                                            println!("\x1b[92mundo\x1b[0m");
                                            if out.is_empty() {
                                                println!("\x1b[94m\x1b[0m");
                                            } else {
                                                println!("\x1b[94m{}\x1b[0m", out);
                                            }
                                        } else {
                                            println!("undo");
                                            println!("{}", out);
                                        }
                                    },
                                    Err(_) => {
                                        // ignore
                                    }
                                }
                            },
                            Err(_) => {}
                        }
                    } else {
                        if use_color {
                            println!("\x1b[92mundo\x1b[0m");
                            println!("\x1b[94m\x1b[0m");
                        } else {
                            println!("undo");
                            println!();
                        }
                    }
                }
                println!();
                continue;
            },
            ":r" | ":redo" => {
                if redo_stack.is_empty() {
                    if use_color {
                        println!("\x1b[91mnothing to redo\r\n\x1b[0m");
                    } else {
                        println!("nothing to redo\r\n");
                    }
                } else {
                    let next = redo_stack.pop().unwrap();
                    history.push(next.clone());
                    // compile whole history
                    let mut combined = String::new();
                    for line in &history {
                        combined.push_str(line);
                        combined.push('\n');
                    }
                    let mut temp_ctx = Context::new();
                    match Parser::new(&combined, &combined).parse_file() {
                        Ok(stmts) => {
                            let mut out = String::new();
                            for stmt in stmts {
                                match temp_ctx.eval_statement(&stmt) {
                                    Ok(r) => out.push_str(&r),
                                    Err(e) => {
                                        if use_color {
                                            println!("\x1b[91m{}\x1b[0m", e.custom_message.unwrap_or_else(|| "error".to_string()));
                                        } else {
                                            println!("{}", e.custom_message.unwrap_or_else(|| "error".to_string()));
                                        }
                                        out.clear();
                                        break;
                                    }
                                }
                            }
                            context = temp_ctx;
                            if use_color {
                                println!("\x1b[92mredo\x1b[0m");
                                println!("\x1b[94m{}\x1b[0m", out);
                            } else {
                                println!("redo");
                                println!("{}", out);
                            }
                        },
                        Err(_) => {}
                    }
                }
                println!();
                continue;
            },
            ":c" | ":clear" => {
                history.clear();
                redo_stack.clear();
                context = Context::new();
                if use_color {
                    println!("\x1b[92mclear\x1b[0m");
                } else {
                    println!("clear");
                }
                println!();
                continue;
            },
            ":s" | ":source" => {
                if history.is_empty() {
                    if use_color {
                        println!("\x1b[91mno lines to print\r\n\x1b[0m");
                    } else {
                        println!("no lines to print\r\n");
                    }
                } else {
                    if use_color {
                        println!("\x1b[92msource\x1b[0m");
                    } else {
                        println!("source");
                    }
                    for (i, line) in history.iter().enumerate() {
                        if use_color {
                            println!("\x1b[2m{}\x1b[0m \x1b[94m{}\x1b[0m", i+1, line.trim());
                        } else {
                            println!("{} {}", i+1, line.trim());
                        }
                    }
                }
                println!();
                continue;
            },
            ":e" | ":exit" => {
                if use_color {
                    println!("\x1b[92mexit\x1b[0m");
                } else {
                    println!("exit");
                }
                break;
            },
            _ => {}
        }

        // Try to compile this line together with history?
        // Original REPL seems to compile cumulative history: each new line is appended and whole file compiled, output is regex of whole file.

        let mut test_history = history.clone();
        test_history.push(input.clone());

        let mut combined = String::new();
        for line in &test_history {
            combined.push_str(line);
            combined.push('\n');
        }

        // Attempt to compile combined
        match compile_melody(&combined, no_color) {
            Ok(compiled) => {
                // compilation succeeded, add to history
                history.push(input.clone());
                redo_stack.clear();
                // For REPL, we need to rebuild context to include new var defs
                // Actually compile_melody already does var tracking but we need context for next iteration? Our compile_melody creates new context each time, so we need to keep context that corresponds to history
                // Let's rebuild context from combined
                let mut temp_ctx = Context::new();
                match Parser::new(&combined, &combined).parse_file() {
                    Ok(stmts) => {
                        for stmt in stmts {
                            let _ = temp_ctx.eval_statement(&stmt);
                        }
                        context = temp_ctx;
                    },
                    Err(_) => {}
                }

                if use_color {
                    println!("\x1b[94m{}\x1b[0m", compiled);
                } else {
                    println!("{}", compiled);
                }
                println!();
            },
            Err(e) => {
                if let Some(msg) = e.custom_message {
                    if use_color {
                        println!("\x1b[91m{}\x1b[0m", msg);
                    } else {
                        println!("{}", msg);
                    }
                } else {
                    // pest-style error
                    if use_color {
                        eprintln!("\x1b[91mError:  --> {}:{}\x1b[0m", e.line, e.col);
                        eprintln!("  |");
                        eprintln!("{} | {}", e.line, e.line_content);
                        eprintln!("  | {}^---", " ".repeat(e.col.saturating_sub(1)));
                        eprintln!("  |");
                        eprintln!("  = {}", e.expected);
                    } else {
                        eprintln!("Error:  --> {}:{}", e.line, e.col);
                        eprintln!("  |");
                        eprintln!("{} | {}", e.line, e.line_content);
                        eprintln!("  | {}^---", " ".repeat(e.col.saturating_sub(1)));
                        eprintln!("  |");
                        eprintln!("  = {}", e.expected);
                    }
                }
                println!();
            }
        }
    }
}
