use clap::{Parser, CommandFactory};
use std::collections::HashMap;
use std::io::{Read, IsTerminal};

#[derive(Parser, Debug)]
#[command(name = "melody", version = "0.20.0", about = "A CLI wrapping the Melody language compiler", disable_help_flag = true, disable_version_flag = true)]
struct Args {
    #[arg(value_name = "INPUT_FILE_PATH", help = "Read from a file\nUse '-' and or pipe input to read from stdin")]
    input: Option<String>,

    #[arg(short = 'o', long = "output", value_name = "OUTPUT_FILE_PATH", help = "Write to a file", conflicts_with_all = ["test", "test_file", "repl", "generate_completions"])]
    output: Option<String>,

    #[arg(short = 'n', long = "no-color", help = "Print output with no color")]
    no_color: bool,

    #[arg(short = 'r', long = "repl", help = "Start the Melody REPL", conflicts_with_all = ["output", "test", "test_file", "generate_completions"])]
    repl: bool,

    #[arg(long = "generate-completions", value_name = "completions", help = "Outputs completions for the selected shell\nTo use, write the output to the appropriate location for your shell", conflicts_with_all = ["output", "repl", "test", "test_file"])]
    generate_completions: Option<String>,

    #[arg(short = 't', long = "test", value_name = "test", help = "Test the compiled regex against a string", conflicts_with_all = ["output", "repl", "test_file", "generate_completions"])]
    test: Option<String>,

    #[arg(short = 'f', long = "test-file", value_name = "test-file", help = "Test the compiled regex against the contents of a file", conflicts_with_all = ["output", "repl", "test", "generate_completions"])]
    test_file: Option<String>,

    #[arg(short = 'h', long = "help", help = "Print help", action = clap::ArgAction::SetTrue)]
    help: bool,

    #[arg(short = 'V', long = "version", help = "Print version", action = clap::ArgAction::SetTrue)]
    version: bool,
}

fn main() {
    // Use clap to parse, but we need to handle colored output for clap errors? Original uses clap error format with "error: ..."
    // We'll let clap handle conflicts, it will print "error: ..." and exit 2, matching original.

    let args = Args::parse();

    if args.help {
        let mut cmd = Args::command();
        let mut buf = Vec::new();
        cmd.write_help(&mut buf).unwrap();
        // The help output in original has no color, just plain.
        println!("{}", String::from_utf8(buf).unwrap());
        std::process::exit(0);
    }
    if args.version {
        println!("melody_cli 0.20.0");
        std::process::exit(0);
    }

    if let Some(shell) = args.generate_completions {
        match shell.as_str() {
            "bash" => {
                print!("{}", BASH_COMPLETION);
                std::process::exit(0);
            },
            "zsh" => {
                print!("{}", ZSH_COMPLETION);
                std::process::exit(0);
            },
            "fish" => {
                print!("{}", FISH_COMPLETION);
                std::process::exit(0);
            },
            "powershell" => {
                print!("{}", POWERSHELL_COMPLETION);
                std::process::exit(0);
            },
            "elvish" => {
                print!("{}", ELVISH_COMPLETION);
                std::process::exit(0);
            },
            _ => {
                eprintln!("Unknown or unsupported shell: '{}'", shell);
                eprintln!("Try one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'");
                eprintln!();
                std::process::exit(0);
            }
        }
    }

    if args.repl {
        let stdin_is_tty = std::io::stdin().is_terminal();
        let stdout_is_tty = std::io::stdout().is_terminal();
        if !stdin_is_tty || !stdout_is_tty {
            eprintln!("Error: repl argument supplied with piped input or output");
            std::process::exit(64);
        }
        repl(args.no_color);
        std::process::exit(0);
    }

    // Determine source
    let source_opt: Option<String> = if let Some(ref p) = args.input {
        if p == "-" {
            let mut buf = String::new();
            std::io::stdin().read_to_string(&mut buf).unwrap();
            Some(buf)
        } else {
            match std::fs::read_to_string(p) {
                Ok(c) => Some(c),
                Err(_) => {
                    eprintln!("Error: unable read file at path {}", p);
                    std::process::exit(65);
                }
            }
        }
    } else {
        if !std::io::stdin().is_terminal() {
            let mut buf = String::new();
            std::io::stdin().read_to_string(&mut buf).unwrap();
            Some(buf)
        } else {
            None
        }
    };

    if source_opt.is_none() {
        // No input file and no piped input
        // Original: in tty, prints colored error message and help, exit 66
        // In non-tty, we saw it prints "\n" (empty) and exit 0
        // Actually for non-tty case, stdin is not tty, so source_opt would be Some("") (empty), not None
        // So this None case only happens when stdin is tty and no file arg
        let is_tty_out = std::io::stdout().is_terminal();
        let use_color = !args.no_color && is_tty_out;
        if use_color {
            eprintln!("\x1b[94mNo input file supplied and no input piped\r\nTry adding a path argument: 'melody ./file.mdy'\x1b[0m\r\n");
        } else {
            eprintln!("No input file supplied and no input piped\r\nTry adding a path argument: 'melody ./file.mdy'\r\n");
        }
        let mut cmd = Args::command();
        let mut buf = Vec::new();
        cmd.write_help(&mut buf).unwrap();
        eprintln!("{}", String::from_utf8(buf).unwrap());
        std::process::exit(66);
    }

    let source = source_opt.unwrap();

    // Compile
    let compiled = match compile_melody(&source, args.no_color) {
        Ok(r) => r,
        Err(e) => {
            e.print(args.no_color);
            std::process::exit(65);
        }
    };

    if let Some(test_str) = args.test {
        let matched = test_regex(&compiled, &test_str);
        let use_color = !args.no_color && std::io::stdout().is_terminal();
        if use_color {
            if matched {
                println!("'{}' \x1b[92mmatched\x1b[0m", test_str);
            } else {
                println!("'{}' \x1b[91mdid not match\x1b[0m", test_str);
            }
        } else {
            if matched {
                println!("'{}' matched", test_str);
            } else {
                println!("'{}' did not match", test_str);
            }
        }
        std::process::exit(0);
    }

    if let Some(test_file_path) = args.test_file {
        let content = match std::fs::read_to_string(&test_file_path) {
            Ok(c) => c,
            Err(_) => {
                eprintln!("Error: unable read file at path {}", test_file_path);
                std::process::exit(74);
            }
        };
        let matched = test_regex(&compiled, &content);
        let use_color = !args.no_color && std::io::stdout().is_terminal();
        if use_color {
            if matched {
                println!("{} \x1b[92mmatched\x1b[0m", test_file_path);
            } else {
                println!("{} \x1b[91mdid not match\x1b[0m", test_file_path);
            }
        } else {
            if matched {
                println!("{} matched", test_file_path);
            } else {
                println!("{} did not match", test_file_path);
            }
        }
        std::process::exit(0);
    }

    if let Some(out_path) = args.output {
        match std::fs::write(&out_path, &compiled) {
            Ok(_) => {},
            Err(_) => {
                eprintln!("Error: {}", out_path);
                std::process::exit(74);
            }
        }
        std::process::exit(0);
    } else {
        // Check if output is tty for color
        let use_color = !args.no_color && std::io::stdout().is_terminal();
        if use_color {
            println!("\x1b[94m{}\x1b[0m", compiled);
        } else {
            println!("{}", compiled);
        }
        std::process::exit(0);
    }
}

fn test_regex(pattern: &str, text: &str) -> bool {
    if pattern.is_empty() {
        // empty regex matches anything? Original: empty source compiled to "" and -t "hi" matched. So empty matches.
        return true;
    }
    match fancy_regex::Regex::new(pattern) {
        Ok(re) => re.is_match(text).unwrap_or(false),
        Err(_) => {
            match regex::Regex::new(pattern) {
                Ok(re) => re.is_match(text),
                Err(_) => false,
            }
        }
    }
}

#[derive(Debug)]
struct CompileError {
    line: usize,
    col: usize,
    line_content: String,
    expected: String,
    // For special errors that are not pest-style but custom
    custom_message: Option<String>,
}

impl CompileError {
    fn print(&self, no_color: bool) {
        if let Some(msg) = &self.custom_message {
            eprintln!("{}", msg);
            return;
        }
        let is_tty = std::io::stderr().is_terminal();
        let use_color = !no_color && is_tty;
        if use_color {
            eprintln!("\x1b[91mError:  --> {}:{}\x1b[0m", self.line, self.col);
            eprintln!("  |");
            eprintln!("{} | {}", self.line, self.line_content);
            let caret = " ".repeat(self.col.saturating_sub(1));
            eprintln!("  | {}^---", caret);
            eprintln!("  |");
            eprintln!("  = {}", self.expected);
        } else {
            eprintln!("Error:  --> {}:{}", self.line, self.col);
            eprintln!("  |");
            eprintln!("{} | {}", self.line, self.line_content);
            let caret = " ".repeat(self.col.saturating_sub(1));
            eprintln!("  | {}^---", caret);
            eprintln!("  |");
            eprintln!("  = {}", self.expected);
        }
    }
}

fn compile_melody(source: &str, _no_color: bool) -> Result<String, CompileError> {
    // Preprocess comments: keep line numbers, remove comment lines where trimmed starts with //
    let lines: Vec<&str> = source.lines().collect();
    let mut processed_lines: Vec<String> = Vec::new();
    for line in lines {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//") {
            processed_lines.push(String::new());
        } else {
            processed_lines.push(line.to_string());
        }
    }
    // Include trailing newline? The original lines handling: if source ends with newline, lines() will not include final empty? But we need to preserve line numbers.
    // If source ends with newline, lines() will give lines without final empty, which is fine.
    // If source is empty, lines is empty, processed_lines empty, we'll have empty source.
    let processed_source = processed_lines.join("\n");

    let mut parser = Parser::new(&processed_source, source);
    match parser.parse_file() {
        Ok(stmts) => {
            let mut ctx = Context::new();
            let mut out = String::new();
            for stmt in stmts {
                match ctx.eval_statement(&stmt) {
                    Ok(r) => out.push_str(&r),
                    Err(e) => return Err(e),
                }
            }
            Ok(out)
        },
        Err(e) => Err(e),
    }
}

