    if let Some(out_path) = output {
        match std::fs::write(&out_path, &compiled) {
            Ok(_) => {},
            Err(_) => {
                eprintln!("Error: {}", out_path);
                std::process::exit(74);
            }
        }
        std::process::exit(0);
    } else {
        let use_color = !no_color && std::io::stdout().is_terminal();
        if use_color {
            println!("\x1b[94m{}\x1b[0m", compiled);
        } else {
            println!("{}", compiled);
        }
        std::process::exit(0);
    }
}

fn test_regex(pattern: &str, text: &str) -> bool {
    if pattern.is_empty() {
        return true;
    }
    match fancy_regex::Regex::new(pattern) {
        Ok(re) => re.is_match(text).unwrap_or(false),
        Err(_) => {
            match regex::Regex::new(pattern) {
                Ok(re) => re.is_match(text),
                Err(_) => false,
            }
        }
    }
}

#[derive(Debug)]
struct CompileError {
    line: usize,
    col: usize,
    line_content: String,
    expected: String,
    custom_message: Option<String>,
}

impl CompileError {
    fn print(&self, no_color: bool) {
        if let Some(msg) = &self.custom_message {
            eprintln!("{}", msg);
            return;
        }
        let is_tty = std::io::stderr().is_terminal();
        let use_color = !no_color && is_tty;
        if use_color {
            eprintln!("\x1b[91mError:  --> {}:{}\x1b[0m", self.line, self.col);
            eprintln!("  |");
            eprintln!("{} | {}", self.line, self.line_content);
            let caret = " ".repeat(self.col.saturating_sub(1));
            eprintln!("  | {}^---", caret);
            eprintln!("  |");
            eprintln!("  = {}", self.expected);
        } else {
            eprintln!("Error:  --> {}:{}", self.line, self.col);
            eprintln!("  |");
            eprintln!("{} | {}", self.line, self.line_content);
            let caret = " ".repeat(self.col.saturating_sub(1));
            eprintln!("  | {}^---", caret);
            eprintln!("  |");
            eprintln!("  = {}", self.expected);
        }
    }
}

fn compile_melody(source: &str, _no_color: bool) -> Result<String, CompileError> {
    // Preprocess comments
    let lines: Vec<&str> = source.lines().collect();
    let mut processed_lines: Vec<String> = Vec::new();
    for line in lines {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//") {
            processed_lines.push(String::new());
        } else {
            processed_lines.push(line.to_string());
        }
    }
    let processed_source = processed_lines.join("\n");
    let mut parser = Parser::new(&processed_source, source);
    match parser.parse_file() {
        Ok(stmts) => {
            let mut ctx = Context::new();
            let mut out = String::new();
            for stmt in stmts {
                match ctx.eval_statement(&stmt) {
                    Ok(r) => out.push_str(&r),
                    Err(e) => return Err(e),
                }
            }
            Ok(out)
        },
        Err(e) => Err(e),
    }
}

#[derive(Debug, Clone, PartialEq)]
enum Symbol {
    Char,
    Space,
    Whitespace,
    Newline,
    Tab,
    Return,
    Feed,
    Backspace,
    Vertical,
    Null,
    Digit,
    Word,
    Start,
    End,
    Boundary,
    Alphabetic,
    Alphanumeric,
}

impl Symbol {
    fn from_str(s: &str) -> Option<Symbol> {
        match s {
            "char" => Some(Symbol::Char),
            "space" => Some(Symbol::Space),
            "whitespace" => Some(Symbol::Whitespace),
            "newline" => Some(Symbol::Newline),
            "tab" => Some(Symbol::Tab),
            "return" => Some(Symbol::Return),
            "feed" => Some(Symbol::Feed),
            "backspace" => Some(Symbol::Backspace),
            "vertical" => Some(Symbol::Vertical),
            "null" => Some(Symbol::Null),
            "digit" => Some(Symbol::Digit),
            "word" => Some(Symbol::Word),
            "start" => Some(Symbol::Start),
            "end" => Some(Symbol::End),
            "boundary" => Some(Symbol::Boundary),
            "alphabetic" => Some(Symbol::Alphabetic),
            "alphanumeric" => Some(Symbol::Alphanumeric),
            _ => None,
        }
    }

    fn to_regex(&self, negated: bool) -> Result<String, CompileError> {
        match self {
            Symbol::Char => {
                if negated {
                    return Err(CompileError {
                        line: 0,
                        col: 0,
                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: negative char not allowed".to_string()),
                    });
                }
                Ok(".".to_string())
            },
            Symbol::Space => Ok(if negated { "[^ ]".to_string() } else { " ".to_string() }),
            Symbol::Whitespace => Ok(if negated { r"\S".to_string() } else { r"\s".to_string() }),
            Symbol::Newline => Ok(if negated { "[^\n]".to_string() } else { r"\n".to_string() }),
            Symbol::Tab => Ok(if negated { "[^\t]".to_string() } else { r"\t".to_string() }),
            Symbol::Return => Ok(if negated { "[^\r]".to_string() } else { r"\r".to_string() }),
            Symbol::Feed => Ok(if negated { "[^\x0C]".to_string() } else { r"\f".to_string() }),
            Symbol::Backspace => Ok(if negated { "[^\x08]".to_string() } else { r"[\b]".to_string() }),
            Symbol::Vertical => Ok(if negated { "[^\x0B]".to_string() } else { r"\v".to_string() }),
            Symbol::Null => Ok(if negated { "[^\0]".to_string() } else { r"\0".to_string() }),
            Symbol::Digit => Ok(if negated { r"\D".to_string() } else { r"\d".to_string() }),
            Symbol::Word => Ok(if negated { r"\W".to_string() } else { r"\w".to_string() }),
            Symbol::Start => {
                if negated {
                    return Err(CompileError {
                        line: 0,
                        col: 0,
                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: negative start not allowed".to_string()),
                    });
                }
                Ok("^".to_string())
            },
            Symbol::End => {
                if negated {
                    return Err(CompileError {
                        line: 0,
                        col: 0,
                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: negative end not allowed".to_string()),
                    });
                }
                Ok("$".to_string())
            },
            Symbol::Boundary => Ok(if negated { r"\B".to_string() } else { r"\b".to_string() }),
            Symbol::Alphabetic => Ok(if negated { "[^a-zA-Z]".to_string() } else { "[a-zA-Z]".to_string() }),
            Symbol::Alphanumeric => Ok(if negated { "[^a-zA-Z0-9]".to_string() } else { "[a-zA-Z0-9]".to_string() }),
        }
    }
}

#[derive(Debug, Clone)]
enum Atom {
    Literal(String),
    Raw(String),
    Symbol(Symbol, bool),
    Range(char, char, bool),
    NotClass(String, bool),
    Group(GroupKind, Vec<Stmt>),
    VarInv(String),
}

#[derive(Debug, Clone)]
enum GroupKind {
    Match,
    Either,
    Capture(Option<String>),
    Ahead,
    Behind,
    NotAhead,
    NotBehind,
}

#[derive(Debug, Clone)]
enum QuantPrefix {
    Some,
    Any,
    Option,
    Exact(usize),
    Range(usize, usize),
    Over(usize),
}

#[derive(Debug, Clone)]
enum Stmt {
    Simple(Atom),
    Quantified(QuantPrefix, bool, Atom),
    VarDecl(String, Vec<Stmt>),
}

struct Context {
    vars: HashMap<String, String>,
}

impl Context {
    fn new() -> Self {
        Context { vars: HashMap::new() }
    }

    fn eval_stmt_list(&mut self, stmts: &[Stmt]) -> Result<String, CompileError> {
        let mut out = String::new();
        for stmt in stmts {
            out.push_str(&self.eval_statement(stmt)?);
        }
        Ok(out)
    }

    fn eval_statement(&mut self, stmt: &Stmt) -> Result<String, CompileError> {
        match stmt {
            Stmt::Simple(atom) => self.eval_atom(atom),
            Stmt::Quantified(prefix, lazy, atom) => {
                match atom {
                    Atom::Group(k, _) => match k {
                        GroupKind::Ahead | GroupKind::Behind | GroupKind::NotAhead | GroupKind::NotBehind => {
                            return Err(CompileError {
                                line: 0,
                                col: 0,
                                line_content: String::new(),
                                expected: String::new(),
                                custom_message: Some("Error: unexpected assertion in quantifier".to_string()),
                            });
                        },
                        _ => {}
                    },
                    Atom::VarInv(_) => {
                        return Err(CompileError {
                            line: 0,
                            col: 0,
                            line_content: String::new(),
                            expected: String::new(),
                            custom_message: Some("Error: unexpected variable invocation in quantifier".to_string()),
                        });
                    },
                    _ => {}
                }
                let base = self.eval_atom(atom)?;
                let result = match prefix {
                    QuantPrefix::Exact(n) => format!("{}{{{}}}", base, n),
                    QuantPrefix::Range(a,b) => format!("{}{{{},{}}}", base, a, b),
                    QuantPrefix::Over(n) => format!("{}{{{},}}", base, n+1),
                    QuantPrefix::Some => format!("{}+", base),
                    QuantPrefix::Any => format!("{}*", base),
                    QuantPrefix::Option => format!("{}?", base),
                };
                if *lazy {
                    Ok(format!("{}?", result))
                } else {
                    Ok(result)
                }
            },
            Stmt::VarDecl(name, body) => {
                let compiled = self.eval_stmt_list(body)?;
                self.vars.insert(name.clone(), compiled);
                Ok(String::new())
            },
        }
    }

    fn eval_atom(&mut self, atom: &Atom) -> Result<String, CompileError> {
        match atom {
            Atom::Literal(s) => Ok(escape_literal(s)),
            Atom::Raw(s) => Ok(s.clone()),
            Atom::Symbol(sym, negated) => {
                match sym.to_regex(*negated) {
                    Ok(r) => Ok(r),
                    Err(e) => Err(e),
                }
            },
            Atom::Range(start, end, negated) => {
                if *negated {
                    Ok(format!("[^{} - {}]", start, end).replace(" ", ""))
                } else {
                    Ok(format!("[{}-{}]", start, end))
                }
            },
            Atom::NotClass(content, negated) => {
                if *negated {
                    Ok(format!("[^{}]", content))
                } else {
                    Ok(format!("[{}]", content))
                }
            },
            Atom::Group(kind, stmts) => {
                // For either, need special handling: each stmt's regex joined with "|"
                match kind {
                    GroupKind::Either => {
                        let mut parts = Vec::new();
                        for s in stmts {
                            parts.push(self.eval_statement(s)?);
                        }
                        Ok(format!("(?:{})", parts.join("|")))
                    },
                    GroupKind::Match => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?:{})", inner))
                    },
                    GroupKind::Capture(opt_name) => {
                        let inner = self.eval_stmt_list(stmts)?;
                        if let Some(name) = opt_name {
                            Ok(format!("(?<{}>{})", name, inner))
                        } else {
                            Ok(format!("({})", inner))
                        }
                    },
                    GroupKind::Ahead => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?={})", inner))
                    },
                    GroupKind::Behind => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?<={})", inner))
                    },
                    GroupKind::NotAhead => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?!{})", inner))
                    },
                    GroupKind::NotBehind => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?<!{})", inner))
                    },
                }
            },
            Atom::VarInv(name) => {
                if let Some(val) = self.vars.get(name) {
                    Ok(val.clone())
                } else {
                    Err(CompileError {
                        line: 0,
                        col: 0,
                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: usage of an uninitialized variable".to_string()),
                    })
                }
            },
        }
    }
}

fn escape_literal(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '.' | '*' | '+' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '|' | '^' | '$' | '\\' => {
                out.push('\\');
                out.push(ch);
            },
            _ => out.push(ch),
        }
    }
    // Escape newlines? Original kept actual newlines as newline char in output (for "\n" literal? Actually literal "\n" as actual newline char should stay newline? But for escaping, newline char is not escaped.
    out
}

struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    col: usize,
    original_lines: Vec<String>,
}

impl<'a> Parser<'a> {
    fn new(processed: &'a str, original: &'a str) -> Self {
        Parser {
            chars: processed.chars().collect(),
            pos: 0,
            line: 1,
            col: 1,
            original_lines: original.lines().map(|s| s.to_string()).collect(),
        }
    }

    fn current(&self) -> Option<char> {
        self.chars.get(self.pos).cloned()
    }

    fn advance(&mut self) {
        if let Some(ch) = self.current() {
            if ch == '\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
            self.pos += 1;
        }
    }

    fn skip_ws(&mut self) {
        while let Some(ch) = self.current() {
            if ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn error(&self, expected: &str) -> CompileError {
        let line_content = if self.line <= self.original_lines.len() {
            self.original_lines[self.line - 1].clone()
        } else if !self.original_lines.is_empty() {
            self.original_lines.last().unwrap().clone()
        } else {
            "".to_string()
        };
        CompileError {
            line: self.line,
            col: self.col,
            line_content,
            expected: expected.to_string(),
            custom_message: None,
        }
    }

    fn error_custom(&self, msg: &str) -> CompileError {
        CompileError {
            line: 0,
            col: 0,
            line_content: String::new(),
            expected: String::new(),
            custom_message: Some(msg.to_string()),
        }
    }

    fn match_keyword(&mut self, kw: &str) -> bool {
        let start_pos = self.pos;
        let start_line = self.line;
        let start_col = self.col;
        self.skip_ws();
        let mut p = self.pos;
        for kc in kw.chars() {
            if p >= self.chars.len() || self.chars[p] != kc {
                self.pos = start_pos;
                self.line = start_line;
                self.col = start_col;
                return false;
            }
            // advance tracking line/col for p
            p += 1;
        }
        // check next char not alphanum or _
        if p < self.chars.len() {
            let nc = self.chars[p];
            if nc.is_ascii_alphanumeric() || nc == '_' {
                self.pos = start_pos;
                self.line = start_line;
                self.col = start_col;
                return false;
            }
        }
        // commit
        // update line/col by advancing through kw
        for _ in kw.chars() {
            self.advance();
        }
        true
    }

    fn parse_file(&mut self) -> Result<Vec<Stmt>, CompileError> {
        let mut stmts = Vec::new();
        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() {
                break;
            }
            match self.parse_stmt() {
                Ok(s) => stmts.push(s),
                Err(e) => return Err(e),
            }
        }
        Ok(stmts)
    }

    fn parse_stmt(&mut self) -> Result<Stmt, CompileError> {
        self.skip_ws();
        if self.pos >= self.chars.len() {
            return Err(self.error("expected root"));
        }

        let pos_before = self.pos;
        let line_before = self.line;
        let col_before = self.col;

        // Try let
        if self.match_keyword("let") {
            self.skip_ws();
            // parse var name .ident
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some('=') {
                return Err(self.error("expected block"));
            }
            self.advance();
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::VarDecl(name, block));
        }
        self.pos = pos_before;
        self.line = line_before;
        self.col = col_before;

        // Try not ahead / not behind (assertion)
        if self.match_keyword("not") {
            self.skip_ws();
            if self.match_keyword("ahead") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotAhead, block)));
            } else if self.match_keyword("behind") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotBehind, block)));
