                                // group atom, no semicolon needed, but check if next char is ";" then that ";" would be considered as start of next statement? Actually for group quantifier, ";" after group is error (expected EOI etc). So we should NOT consume ";", and if there is ";", we should error? Let's see: "some of match { "a"; };" gave error expected EOI etc at ";". So if after group atom there is ";", we should error with expected EOI etc.

                                self.skip_ws();
                                if self.current() == Some(';') {
                                    return Err(self.error("expected EOI, literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"));
                                }
                                return Ok(Stmt::Quantified(prefix, lazy, atom));
                            }
                        },
                        Err(e) => {
                            // Atom parsing failed, return its error
                            return Err(e);
                        }
                    }
                }
            } else {
                // No quant prefix, restore
                self.pos = save_pos;
                self.line = save_line;
                self.col = save_col;
            }
        }

        // Try simple atoms that require semicolon: literal, raw, symbol, range, not class, var invocation

        // First try to parse not class/range/symbol
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if self.match_keyword("not") {
                self.skip_ws();
                // Try parse range first: char to char
                if let Ok((start, end)) = self.parse_range_no_semi() {
                    self.skip_ws();
                    if self.current() != Some(';') {
                        // Expected amount or assertion_type? Let's see: "not a to z" without semicolon error expected amount or assertion_type
                        return Err(self.error("expected amount or assertion_type"));
                    }
                    self.advance();
                    return Ok(Stmt::Simple(Atom::Range(start, end, true)));
                }
                // Reset and try symbol?
                self.pos = save;
                self.line = sl;
                self.col = sc;
                // Re-parse not
                self.match_keyword("not");
                self.skip_ws();
                // Try symbol: <ident>
                if self.current() == Some('<') {
                    // parse symbol
                    match self.parse_symbol_atom() {
                        Ok((sym, negated)) => {
                            // negated is already true because we are in not
                            // Actually parse_symbol_atom for negated case should produce negated true
                            self.skip_ws();
                            if self.current() != Some(';') {
                                return Err(self.error("expected amount or assertion_type"));
                            }
                            self.advance();
                            // Check for negative start/end/char errors
                            match sym {
                                Symbol::Start => return Err(self.error_custom("Error: negative start not allowed")),
                                Symbol::End => return Err(self.error_custom("Error: negative end not allowed")),
                                Symbol::Char => return Err(self.error_custom("Error: negative char not allowed")),
                                _ => {}
                            }
                            return Ok(Stmt::Simple(Atom::Symbol(sym, true)));
                        },
                        Err(_) => {
                            // try class content?
                        }
                    }
                }
                // Try class_content: sequence that is class_content?
                self.pos = save;
                self.line = sl;
                self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                // Parse class_content string until ; with our allowed chars?
                // For simplicity, we will parse up to ';' collecting characters that are allowed as class_content (including spaces)
                // But we need to fail if content contains invalid chars like ", ', `, <, >, etc that are not allowed as class_content.
                // Our earlier allowed list for class_content single char excluded many symbols. For multi-char, we saw "not a-b;" fails, "not a+b;" fails, etc.
                // We'll implement: class_content = one or more of allowed chars and spaces? But "not a b;" allowed, which includes space. So we need to allow spaces inside.

                // We'll attempt to collect until ';' and validate.

                let mut content = String::new();
                let mut has_content = false;
                while let Some(ch) = self.current() {
                    if ch == ';' {
                        break;
                    }
                    // If ch is '"' or "'" or '`' or '<' or '>' or '(' or ')' or '[' or ']' or '{' or '}' or '|' or '?' or '.' or ':' or '=' etc that are not allowed, we should error.

                    // For simplicity, we will check if ch is allowed as per earlier allowed list plus space and plus letters/digits for "of" "to" etc.

                    // Actually we need to allow "of" and "to" words inside class_content, which include letters, spaces.

                    // Let's define allowed chars for class_content: letters, digits, underscore, space, and ! @ # % & * $ ^ \ and maybe others? From earlier allowed single char list: ! # $ % & * 0-9 @ A-Z \ ^ _ a-z

                    // But "not a b;" includes space and letters, allowed.

                    // "not a-b;" includes '-' which we said denied -> should error.

                    // So we will allow only chars in allowed set plus space.

                    // If we encounter char not in allowed set and not space and not ';', then it's invalid -> error expected amount or assertion_type or expected amount, class_content, or assertion_type etc.

                    // To match original errors, we need to produce correct expected message.

                    // For "not a-b;", error was expected amount or assertion_type (since '-' not allowed, but parser expected amount or assertion_type after not?)

                    // For "not a;" success.

                    // Let's implement validation: if ch is in allowed set or space, collect; else error.

                    // Allowed set: A-Z, a-z, 0-9, _, !, @, #, $, %, &, *, ^, \, and space? Also maybe other symbols like $ etc.

                    // From our earlier allowed single char list: ! # $ % & * 0-9 @ A-Z \ ^ _ a-z plus maybe other? We had _ also.

                    // What about '+'? '+' was denied as single char, but "not a+b;" failed. So '+' not allowed.

                    // What about '/'? denied, fails.

                    // What about '?'? denied.

                    // '.' denied.

                    // ':' denied.

                    // '=' denied.

                    // '(' denied, etc.

                    if ch == ' ' {
                        content.push(ch);
                        self.advance();
                        has_content = true;
                        continue;
                    }
                    let allowed = ch.is_ascii_alphanumeric() || ch == '_' || ch == '!' || ch == '@' || ch == '#' || ch == '$' || ch == '%' || ch == '&' || ch == '*' || ch == '\\' || ch == '^';
                    if allowed {
                        content.push(ch);
                        self.advance();
                        has_content = true;
                    } else {
                        // Invalid char for class_content
                        // Return error expected amount or assertion_type (or other variant)
                        // We need to decide which expected message to produce based on context. For "not" alone, we have different messages: sometimes "expected amount, class_content, or assertion_type", sometimes "expected amount or assertion_type".
                        // For "not a-b;" where '-' is invalid, error is "expected amount or assertion_type"
                        // For "not;" (no content), error is "expected amount, class_content, or assertion_type"
                        // For "not <invalid symbol>"? The error for "<>" invalid symbol gave "usage of an unrecognized symbol" not expected.

                        // Let's produce "expected amount or assertion_type" for now for invalid char inside class_content after some content?

                        return Err(self.error("expected amount or assertion_type"));
                    }
                }

                if !has_content {
                    return Err(self.error("expected amount, class_content, or assertion_type"));
                }

                // After collecting content, we need to check if content is actually a range pattern? We already attempted range first, but if content is "a to z", it would have been parsed as range. So here content is not range, it's class_content.

                // Trim? The content may have leading/trailing spaces? "not a b;" content "a b" includes space.

                // We should trim? No, keep as is? For output we need to produce [^content] where content is as collected, but trimmed? For "not a b;" content "a b" => [^a b] (keeps space). For "not 2 of a to z;" content "2 of a to z" => [^2 of a to z] keeps spaces.

                // So we keep content as is (including spaces) but we need to ensure we didn't include trailing spaces before semicolon.

                self.skip_ws(); // Actually content may have trailing spaces? Our loop collected spaces, but before semicolon there might be spaces. In "not a to z;" with range, we already handled range. For class_content, "not abc;" has no spaces.

                // Now expect semicolon
                if self.current() != Some(';') {
                    return Err(self.error("expected amount or assertion_type"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::NotClass(content, true)));
            }
        }

        // Try range: char to char
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if let Ok((start, end)) = self.parse_range_no_semi() {
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected root"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::Range(start, end, false)));
            }
            self.pos = save;
            self.line = sl;
            self.col = sc;
        }

        // Try symbol: <ident>
        if self.current() == Some('<') {
            match self.parse_symbol_atom() {
                Ok((sym, negated)) => {
                    self.skip_ws();
                    if self.current() != Some(';') {
                        return Err(self.error("expected root"));
                    }
                    self.advance();
                    return Ok(Stmt::Simple(Atom::Symbol(sym, negated)));
                },
                Err(e) => {
                    // If custom message about unrecognized symbol, return
                    if e.custom_message.is_some() {
                        return Err(e);
                    }
                    // else continue
                }
            }
        }

        // Try literal: " or '
        if self.current() == Some('"') || self.current() == Some('\'') {
            let lit = self.parse_literal()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Literal(lit)));
        }

        // Try raw: `
        if self.current() == Some('`') {
            let raw = self.parse_raw()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Raw(raw)));
        }

        // Try variable invocation: .ident
        if self.current() == Some('.') {
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::VarInv(name)));
        }

        // Nothing matched => expected root
        Err(self.error("expected root"))
    }

    fn parse_ident(&mut self) -> Result<String, CompileError> {
        self.skip_ws();
        let mut ident = String::new();
        while let Some(ch) = self.current() {
            if ch.is_ascii_alphabetic() || ch == '_' {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        if ident.is_empty() {
            return Err(self.error("expected block or identifier"));
        }
        Ok(ident)
    }

    fn parse_var_name(&mut self) -> Result<String, CompileError> {
        self.skip_ws();
        if self.current() != Some('.') {
            return Err(self.error("expected identifier"));
        }
        self.advance();
        let mut name = String::new();
        while let Some(ch) = self.current() {
            if ch.is_ascii_alphabetic() || ch == '_' {
                name.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        if name.is_empty() {
            return Err(self.error("expected identifier"));
        }
        Ok(name)
    }

    fn parse_symbol_atom(&mut self) -> Result<(Symbol, bool), CompileError> {
        // assumes current is '<'
        if self.current() != Some('<') {
            return Err(self.error("expected symbol_identifier"));
        }
        self.advance();
        let mut ident = String::new();
        while let Some(ch) = self.current() {
            if ch == '>' {
                break;
            }
            if ch == '\n' || ch == '\r' {
                return Err(self.error("expected symbol_identifier"));
            }
            ident.push(ch);
            self.advance();
        }
        if self.current() != Some('>') {
            return Err(self.error("expected symbol_identifier"));
        }
        self.advance();
        // ident may have spaces? Trim?
        let trimmed = ident.trim();
        if let Some(sym) = Symbol::from_str(trimmed) {
            Ok((sym, false))
        } else {
            Err(CompileError {
                line: 0,
                col: 0,
                line_content: String::new(),
                expected: String::new(),
                custom_message: Some("Error: usage of an unrecognized symbol".to_string()),
            })
        }
    }

    fn parse_literal(&mut self) -> Result<String, CompileError> {
        let quote = self.current().unwrap();
        if quote != '"' && quote != '\'' {
            return Err(self.error("expected root"));
        }
        let is_double = quote == '"';
        self.advance();
        let mut content = String::new();
        while let Some(ch) = self.current() {
            if ch == '\\' {
                // escape
                self.advance();
                if let Some(esc) = self.current() {
                    match esc {
                        'n' => { content.push('\\'); content.push('n'); self.advance(); },
                        't' => { content.push('\\'); content.push('t'); self.advance(); },
                        'r' => { content.push('\\'); content.push('r'); self.advance(); },
                        'f' => { content.push('\\'); content.push('f'); self.advance(); },
                        'b' => { content.push('\\'); content.push('b'); self.advance(); },
                        '/' => { content.push('\\'); content.push('/'); self.advance(); },
                        '\\' => { content.push('\\'); content.push('\\'); self.advance(); },
                        '"' => {
                            if is_double {
                                content.push('"');
                                self.advance();
                            } else {
                                return Err(self.error("expected root"));
                            }
                        },
                        '\'' => {
                            if !is_double {
                                content.push('\'');
                                self.advance();
                            } else {
                                return Err(self.error("expected root"));
                            }
                        },
                        _ => {
                            return Err(self.error("expected root"));
                        }
                    }
                } else {
                    return Err(self.error("expected root"));
                }
            } else if ch == '"' && is_double {
                self.advance();
                break;
            } else if ch == '\'' && !is_double {
                self.advance();
                break;
            } else {
                // regular char, including actual newline, tab, etc
                content.push(ch);
                self.advance();
            }
        }
        Ok(content)
    }

    fn parse_raw(&mut self) -> Result<String, CompileError> {
        if self.current() != Some('`') {
            return Err(self.error("expected root"));
        }
        self.advance();
        let mut content = String::new();
        while let Some(ch) = self.current() {
            if ch == '\\' {
                self.advance();
                if let Some(esc) = self.current() {
                    if esc == '`' {
                        content.push('`');
                        self.advance();
                    } else if esc == '\\' {
                        content.push('\\');
                        content.push('\\');
                        self.advance();
                    } else {
                        return Err(self.error("expected root"));
                    }
                } else {
                    return Err(self.error("expected root"));
                }
            } else if ch == '`' {
                self.advance();
                break;
            } else {
                content.push(ch);
                self.advance();
            }
        }
        Ok(content)
    }

    fn parse_range_no_semi(&mut self) -> Result<(char, char), CompileError> {
        self.skip_ws();
        // Need to parse single char as start
        let start = match self.current() {
            Some(c) if c != ' ' && c != '\t' && c != '\r' && c != '\n' && c != ';' && c != '{' && c != '}' => c,
            _ => return Err(self.error("expected root")),
        };
        // Check if start char is followed by "to" even without space? We need to look ahead
        // Save pos after start
        let start_pos = self.pos;
        let start_line = self.line;
        let start_col = self.col;
        self.advance();
        self.skip_ws();
        // Expect "to"
        if !self.match_keyword("to") {
            self.pos = start_pos;
            self.line = start_line;
            self.col = start_col;
            return Err(self.error("expected root"));
        }
        self.skip_ws();
        let end = match self.current() {
            Some(c) if c != ' ' && c != '\t' && c != '\r' && c != '\n' && c != ';' && c != '{' && c != '}' => c,
            _ => return Err(self.error("expected root")),
        };
        self.advance();
        Ok((start, end))
    }

    fn parse_quant_prefix(&mut self) -> Option<QuantPrefix> {
        self.skip_ws();
        let save = self.pos;
        let sl = self.line;
        let sc = self.col;

        if self.match_keyword("some") {
            return Some(QuantPrefix::Some);
        }
        self.pos = save; self.line = sl; self.col = sc;
        if self.match_keyword("any") {
            return Some(QuantPrefix::Any);
        }
        self.pos = save; self.line = sl; self.col = sc;
        if self.match_keyword("option") {
            return Some(QuantPrefix::Option);
        }
        self.pos = save; self.line = sl; self.col = sc;
        if self.match_keyword("over") {
            self.skip_ws();
            // parse number
            if let Some(n) = self.parse_number() {
                return Some(QuantPrefix::Over(n));
            } else {
                self.pos = save; self.line = sl; self.col = sc;
                return None;
            }
        }
        // Try number
        if let Some(n) = self.parse_number() {
            self.skip_ws();
            if self.match_keyword("to") {
                self.skip_ws();
                if let Some(m) = self.parse_number() {
                    return Some(QuantPrefix::Range(n, m));
                } else {
                    // If second number missing, we should error? For "2 to" without second number, original gave expected amount
                    // We'll return Range with 0 and let caller handle? Actually we need to produce error "expected amount"
                    // For simplicity, if second number missing, return None and let outer produce error
                    self.pos = save; self.line = sl; self.col = sc;
                    return None;
                }
            } else {
                return Some(QuantPrefix::Exact(n));
            }
        }
        None
    }

    fn parse_number(&mut self) -> Option<usize> {
        self.skip_ws();
        let mut num_str = String::new();
        while let Some(ch) = self.current() {
            if ch.is_ascii_digit() {
                num_str.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        if num_str.is_empty() {
            None
        } else {
            num_str.parse().ok()
        }
    }

    fn parse_atom_for_quant(&mut self) -> Result<Atom, CompileError> {
        self.skip_ws();
        // Atom can be literal, raw, symbol, range, not, group
        // For quantifier, we should allow literal, raw, symbol, range, not, group (but not assertion)

        // Try not
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if self.match_keyword("not") {
                self.skip_ws();
                // Try range
                if let Ok((s,e)) = self.parse_range_no_semi() {
                    return Ok(Atom::Range(s,e,true));
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                if self.current() == Some('<') {
                    if let Ok((sym,_)) = self.parse_symbol_atom() {
                        // Check negative start/end/char handled later
                        return Ok(Atom::Symbol(sym, true));
                    }
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                // class content?
                let mut content = String::new();
                let mut has = false;
                while let Some(ch) = self.current() {
                    if ch == ';' || ch == '{' || ch == '}' || ch == '\n' {
                        break;
                    }
                    // allowed for class_content? Use same as before
                    if ch.is_ascii_alphanumeric() || ch == '_' || ch == ' ' || ch == '!' || ch == '@' || ch == '#' || ch == '$' || ch == '%' || ch == '&' || ch == '*' || ch == '\\' || ch == '^' {
                        content.push(ch);
                        self.advance();
                        has = true;
                    } else {
                        break;
                    }
                }
                if has {
                    return Ok(Atom::NotClass(content, true));
                }
                return Err(self.error("expected amount, class_content, or assertion_type"));
            }
        }

        // Try range
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if let Ok((s,e)) = self.parse_range_no_semi() {
                return Ok(Atom::Range(s,e,false));
            }
            self.pos = save; self.line = sl; self.col = sc;
        }

        // Try symbol
        if self.current() == Some('<') {
            if let Ok((sym, _)) = self.parse_symbol_atom() {
                return Ok(Atom::Symbol(sym, false));
            }
        }

        // Try literal
        if self.current() == Some('"') || self.current() == Some('\'') {
            let lit = self.parse_literal()?;
            return Ok(Atom::Literal(lit));
        }

        // Try raw
        if self.current() == Some('`') {
            let raw = self.parse_raw()?;
            return Ok(Atom::Raw(raw));
        }

        // Try groups
        if self.match_keyword("match") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Atom::Group(GroupKind::Match, block));
        }
        if self.match_keyword("either") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Atom::Group(GroupKind::Either, block));
        }
        if self.match_keyword("capture") {
            self.skip_ws();
            let mut opt_name = None;
            if let Some(ch) = self.current() {
                if ch.is_ascii_alphabetic() || ch == '_' {
                    let ident = self.parse_ident()?;
                    opt_name = Some(ident);
                    self.skip_ws();
                }
            }
            if self.current() != Some('{') {
                if opt_name.is_none() {
                    return Err(self.error("expected block or identifier"));
                } else {
                    return Err(self.error("expected block"));
                }
            }
            let block = self.parse_block()?;
            return Ok(Atom::Group(GroupKind::Capture(opt_name), block));
        }
        if self.match_keyword("ahead") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Atom::Group(GroupKind::Ahead, block));
        }
        if self.match_keyword("behind") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Atom::Group(GroupKind::Behind, block));
        }

        Err(self.error("expected literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"))
    }

    fn parse_block(&mut self) -> Result<Vec<Stmt>, CompileError> {
        self.skip_ws();
        if self.current() != Some('{') {
            return Err(self.error("expected block"));
        }
        self.advance();
        let mut stmts = Vec::new();
        loop {
            self.skip_ws();
            if self.current() == Some('}') {
                self.advance();
                break;
            }
            if self.pos >= self.chars.len() {
                return Err(self.error("expected block"));
            }
            match self.parse_stmt_inside_block() {
                Ok(s) => stmts.push(s),
                Err(e) => return Err(e),
            }
        }
        Ok(stmts)
    }

    fn parse_stmt_inside_block(&mut self) -> Result<Stmt, CompileError> {
        // Inside block, similar to top-level but statement termination rules slightly different?
        // For simplicity, we will parse similarly to parse_stmt but without handling var decl? var decl also allowed.

        // We'll reuse parse_stmt logic but need to avoid infinite loop.

        // For inside block, we have same possibilities but groups and var decl also.

        // Let's call a helper that parses a statement without consuming outer file EOF.

        self.skip_ws();
        if self.pos >= self.chars.len() {
            return Err(self.error("expected block"));
        }

        // Try let
        let pos_before = self.pos;
        let line_before = self.line;
        let col_before = self.col;

        if self.match_keyword("let") {
            self.skip_ws();
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some('=') {
                return Err(self.error("expected block"));
            }
            self.advance();
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::VarDecl(name, block));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;

        // Try not ahead/behind
        if self.match_keyword("not") {
            self.skip_ws();
            if self.match_keyword("ahead") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotAhead, block)));
            } else if self.match_keyword("behind") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotBehind, block)));
            } else {
                self.pos = pos_before; self.line = line_before; self.col = col_before;
            }
        }

        // Groups
        if self.match_keyword("match") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Match, block)));
        }
        if self.match_keyword("either") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Either, block)));
        }
        if self.match_keyword("capture") {
            self.skip_ws();
            let mut opt_name = None;
            if let Some(ch) = self.current() {
                if ch.is_ascii_alphabetic() || ch == '_' {
                    let ident = self.parse_ident()?;
                    opt_name = Some(ident);
                    self.skip_ws();
                }
            }
            if self.current() != Some('{') {
                if opt_name.is_none() {
                    return Err(self.error("expected block or identifier"));
                } else {
                    return Err(self.error("expected block"));
                }
            }
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Capture(opt_name), block)));
        }
        if self.match_keyword("ahead") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Ahead, block)));
        }
        if self.match_keyword("behind") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Behind, block)));
        }

        // Quantifier
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            let mut lazy = false;
            self.skip_ws();
            if self.match_keyword("lazy") {
                lazy = true;
                self.skip_ws();
            }
            if let Some(prefix) = self.parse_quant_prefix() {
                self.skip_ws();
                if !self.match_keyword("of") {
                    self.pos = save; self.line = sl; self.col = sc;
                } else {
                    self.skip_ws();
                    match self.parse_atom_for_quant() {
                        Ok(atom) => {
                            // Check if needs semicolon inside block? For block, after literal etc, need semicolon as terminator.
                            // For groups inside block, no semicolon.
                            let needs_semi = match atom {
                                Atom::Literal(_) | Atom::Raw(_) | Atom::Symbol(_,_) | Atom::Range(_,_,_) | Atom::NotClass(_,_) => true,
                                _ => false,
                            };
                            if needs_semi {
                                self.skip_ws();
                                if self.current() != Some(';') {
                                    return Err(self.error("expected group_declaration, assertion_declaration, or variable_declaration"));
                                }
                                self.advance();
                                return Ok(Stmt::Quantified(prefix, lazy, atom));
                            } else {
                                self.skip_ws();
                                if self.current() == Some(';') {
                                    return Err(self.error("expected quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
                                }
                                return Ok(Stmt::Quantified(prefix, lazy, atom));
                            }
                        },
                        Err(e) => return Err(e),
                    }
                }
            } else {
                self.pos = save; self.line = sl; self.col = sc;
            }
        }

        // Simple atoms with semicolon
        // Try not
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if self.match_keyword("not") {
                self.skip_ws();
                if let Ok((s,e)) = self.parse_range_no_semi() {
                    self.skip_ws();
                    if self.current() != Some(';') {
                        return Err(self.error("expected amount or assertion_type"));
                    }
                    self.advance();
                    return Ok(Stmt::Simple(Atom::Range(s,e,true)));
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                if self.current() == Some('<') {
                    if let Ok((sym,_)) = self.parse_symbol_atom() {
                        self.skip_ws();
                        if self.current() != Some(';') {
                            return Err(self.error("expected amount or assertion_type"));
                        }
                        self.advance();
                        match sym {
                            Symbol::Start => return Err(self.error_custom("Error: negative start not allowed")),
                            Symbol::End => return Err(self.error_custom("Error: negative end not allowed")),
                            Symbol::Char => return Err(self.error_custom("Error: negative char not allowed")),
                            _ => {}
                        }
                        return Ok(Stmt::Simple(Atom::Symbol(sym, true)));
                    }
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                let mut content = String::new();
                let mut has = false;
                while let Some(ch) = self.current() {
                    if ch == ';' { break; }
                    if ch.is_ascii_alphanumeric() || ch == '_' || ch == ' ' || ch == '!' || ch == '@' || ch == '#' || ch == '$' || ch == '%' || ch == '&' || ch == '*' || ch == '\\' || ch == '^' {
                        content.push(ch);
                        self.advance();
                        has = true;
                    } else {
                        break;
                    }
                }
                if !has {
                    return Err(self.error("expected amount, class_content, or assertion_type"));
                }
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected amount or assertion_type"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::NotClass(content, true)));
            }
        }

        // range
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if let Ok((s,e)) = self.parse_range_no_semi() {
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected root"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::Range(s,e,false)));
            }
            self.pos = save; self.line = sl; self.col = sc;
        }

        // symbol
        if self.current() == Some('<') {
            if let Ok((sym,_)) = self.parse_symbol_atom() {
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected root"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::Symbol(sym, false)));
            }
        }

        // literal
        if self.current() == Some('"') || self.current() == Some('\'') {
            let lit = self.parse_literal()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Literal(lit)));
        }

        // raw
        if self.current() == Some('`') {
            let raw = self.parse_raw()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Raw(raw)));
        }

        // var invocation
        if self.current() == Some('.') {
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::VarInv(name)));
        }

        Err(self.error("expected root"))
    }
}

const BASH_COMPLETION: &str = r#"_melody() {
    local i cur prev opts cmd
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    cmd=""
    opts=""

    for i in ${COMP_WORDS[@]}
    do
        case "${cmd},${i}" in
            ",$1")
                cmd="melody"
                ;;
            *)
                ;;
        esac
    done

    case "${cmd}" in
        melody)
            opts="-o -n -r -t -f -h -V --output --no-color --repl --generate-completions --test --test-file --help --version [INPUT_FILE_PATH]"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- "${cur}") )
                return 0
            fi
            case "${prev}" in
                --output)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -o)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --generate-completions)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --test)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -t)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --test-file)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -f)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W "${opts}" -- "${cur}") )
            return 0
            ;;
    esac
}

