                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: negative char not allowed".to_string()),
                    });
                }
                Ok(".".to_string())
            },
            Symbol::Space => Ok(if negated { "[^ ]".to_string() } else { " ".to_string() }),
            Symbol::Whitespace => Ok(if negated { r"\S".to_string() } else { r"\s".to_string() }),
            Symbol::Newline => Ok(if negated { "[^\n]".to_string() } else { r"\n".to_string() }),
            Symbol::Tab => Ok(if negated { "[^\t]".to_string() } else { r"\t".to_string() }),
            Symbol::Return => Ok(if negated { "[^\r]".to_string() } else { r"\r".to_string() }),
            Symbol::Feed => Ok(if negated { "[^\\f]".to_string() } else { r"\f".to_string() }),
            Symbol::Backspace => Ok(if negated { "[^\\b]".to_string() } else { r"[\b]".to_string() }),
            Symbol::Vertical => Ok(if negated { "[^\\v]".to_string() } else { r"\v".to_string() }),
            Symbol::Null => Ok(if negated { "[^\\0]".to_string() } else { r"\0".to_string() }),
            Symbol::Digit => Ok(if negated { r"\D".to_string() } else { r"\d".to_string() }),
            Symbol::Word => Ok(if negated { r"\W".to_string() } else { r"\w".to_string() }),
            Symbol::Start => {
                if negated {
                    return Err(CompileError {
                        line: 0,
                        col: 0,
                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: negative start not allowed".to_string()),
                    });
                }
                Ok("^".to_string())
            },
            Symbol::End => {
                if negated {
                    return Err(CompileError {
                        line: 0,
                        col: 0,
                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: negative end not allowed".to_string()),
                    });
                }
                Ok("$".to_string())
            },
            Symbol::Boundary => Ok(if negated { r"\B".to_string() } else { r"\b".to_string() }),
            Symbol::Alphabetic => Ok(if negated { "[^a-zA-Z]".to_string() } else { "[a-zA-Z]".to_string() }),
            Symbol::Alphanumeric => Ok(if negated { "[^a-zA-Z0-9]".to_string() } else { "[a-zA-Z0-9]".to_string() }),
        }
    }
}

#[derive(Debug, Clone)]
enum Atom {
    Literal(String),
    Raw(String),
    Symbol(Symbol, bool),
    Range(char, char, bool),
    NotClass(String, bool),
    Group(GroupKind, Vec<Stmt>),
    VarInv(String),
}

#[derive(Debug, Clone)]
enum GroupKind {
    Match,
    Either,
    Capture(Option<String>),
    Ahead,
    Behind,
    NotAhead,
    NotBehind,
}

#[derive(Debug, Clone)]
enum QuantPrefix {
    Some,
    Any,
    Option,
    Exact(usize),
    Range(usize, usize),
    Over(usize),
}

#[derive(Debug, Clone)]
enum Stmt {
    Simple(Atom),
    Quantified(QuantPrefix, bool, Atom),
    VarDecl(String, Vec<Stmt>),
}

struct Context {
    vars: HashMap<String, String>,
}

impl Context {
    fn new() -> Self {
        Context { vars: HashMap::new() }
    }

    fn eval_stmt_list(&mut self, stmts: &[Stmt]) -> Result<String, CompileError> {
        let mut out = String::new();
        for stmt in stmts {
            out.push_str(&self.eval_statement(stmt)?);
        }
        Ok(out)
    }

    fn eval_statement(&mut self, stmt: &Stmt) -> Result<String, CompileError> {
        match stmt {
            Stmt::Simple(atom) => self.eval_atom(atom),
            Stmt::Quantified(prefix, lazy, atom) => {
                match atom {
                    Atom::Group(k, _) => match k {
                        GroupKind::Ahead | GroupKind::Behind | GroupKind::NotAhead | GroupKind::NotBehind => {
                            return Err(CompileError {
                                line: 0,
                                col: 0,
                                line_content: String::new(),
                                expected: String::new(),
                                custom_message: Some("Error: unexpected assertion in quantifier".to_string()),
                            });
                        },
                        _ => {}
                    },
                    Atom::VarInv(_) => {
                        return Err(CompileError {
                            line: 0,
                            col: 0,
                            line_content: String::new(),
                            expected: String::new(),
                            custom_message: Some("Error: unexpected variable invocation in quantifier".to_string()),
                        });
                    },
                    _ => {}
                }
                let base = self.eval_atom(atom)?;
                let result = match prefix {
                    QuantPrefix::Exact(n) => {
                        // Check invalid range like over? Actually exact doesn't need range check
                        format!("{}{{{}}}", base, n)
                    },
                    QuantPrefix::Range(a,b) => {
                        if a > *b {
                            return Err(CompileError {
                                line: 0,
                                col: 0,
                                line_content: String::new(),
                                expected: String::new(),
                                custom_message: Some("Error: usage of an invalid quantifier range".to_string()),
                            });
                        }
                        format!("{}{{{},{}}}", base, a, b)
                    },
                    QuantPrefix::Over(n) => format!("{}{{{},}}", base, n+1),
                    QuantPrefix::Some => format!("{}+", base),
                    QuantPrefix::Any => format!("{}*", base),
                    QuantPrefix::Option => format!("{}?", base),
                };
                if *lazy {
                    Ok(format!("{}?", result))
                } else {
                    Ok(result)
                }
            },
            Stmt::VarDecl(name, body) => {
                let compiled = self.eval_stmt_list(body)?;
                self.vars.insert(name.clone(), compiled);
                Ok(String::new())
            },
        }
    }

    fn eval_atom(&mut self, atom: &Atom) -> Result<String, CompileError> {
        match atom {
            Atom::Literal(s) => Ok(escape_literal(s)),
            Atom::Raw(s) => Ok(s.clone()),
            Atom::Symbol(sym, negated) => sym.to_regex(*negated),
            Atom::Range(start, end, negated) => {
                if *negated {
                    Ok(format!("[^{}-{}]", start, end))
                } else {
                    Ok(format!("[{}-{}]", start, end))
                }
            },
            Atom::NotClass(content, negated) => {
                if *negated {
                    Ok(format!("[^{}]", content))
                } else {
                    Ok(format!("[{}]", content))
                }
            },
            Atom::Group(kind, stmts) => {
                match kind {
                    GroupKind::Either => {
                        let mut parts = Vec::new();
                        for s in stmts {
                            parts.push(self.eval_statement(s)?);
                        }
                        Ok(format!("(?:{})", parts.join("|")))
                    },
                    GroupKind::Match => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?:{})", inner))
                    },
                    GroupKind::Capture(opt_name) => {
                        let inner = self.eval_stmt_list(stmts)?;
                        if let Some(name) = opt_name {
                            Ok(format!("(?<{}>{})", name, inner))
                        } else {
                            Ok(format!("({})", inner))
                        }
                    },
                    GroupKind::Ahead => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?={})", inner))
                    },
                    GroupKind::Behind => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?<={})", inner))
                    },
                    GroupKind::NotAhead => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?!{})", inner))
                    },
                    GroupKind::NotBehind => {
                        let inner = self.eval_stmt_list(stmts)?;
                        Ok(format!("(?<!{})", inner))
                    },
                }
            },
            Atom::VarInv(name) => {
                if let Some(val) = self.vars.get(name) {
                    Ok(val.clone())
                } else {
                    Err(CompileError {
                        line: 0,
                        col: 0,
                        line_content: String::new(),
                        expected: String::new(),
                        custom_message: Some("Error: usage of an uninitialized variable".to_string()),
                    })
                }
            },
        }
    }
}

fn escape_literal(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '.' | '*' | '+' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '|' | '^' | '$' | '\\' => {
                out.push('\\');
                out.push(ch);
            },
            _ => out.push(ch),
        }
    }
    out
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    col: usize,
    original_lines: Vec<String>,
}

impl Parser {
    fn new(processed: String, original: String) -> Self {
        Parser {
            chars: processed.chars().collect(),
            pos: 0,
            line: 1,
            col: 1,
            original_lines: original.lines().map(|s| s.to_string()).collect(),
        }
    }

    fn current(&self) -> Option<char> {
        self.chars.get(self.pos).cloned()
    }

    fn advance(&mut self) {
        if let Some(ch) = self.current() {
            if ch == '\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
            self.pos += 1;
        }
    }

    fn skip_ws(&mut self) {
        while let Some(ch) = self.current() {
            if ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn error(&self, expected: &str) -> CompileError {
        let line_content = if self.line <= self.original_lines.len() {
            self.original_lines[self.line - 1].clone()
        } else if !self.original_lines.is_empty() {
            self.original_lines.last().unwrap().clone()
        } else {
            "".to_string()
        };
        CompileError {
            line: self.line,
            col: self.col,
            line_content,
            expected: expected.to_string(),
            custom_message: None,
        }
    }

    fn error_custom(&self, msg: &str) -> CompileError {
        CompileError {
            line: 0,
            col: 0,
            line_content: String::new(),
            expected: String::new(),
            custom_message: Some(msg.to_string()),
        }
    }

    fn match_keyword(&mut self, kw: &str) -> bool {
        let start_pos = self.pos;
        let start_line = self.line;
        let start_col = self.col;
        self.skip_ws();
        let mut p = self.pos;
        for kc in kw.chars() {
            if p >= self.chars.len() || self.chars[p] != kc {
                self.pos = start_pos;
                self.line = start_line;
                self.col = start_col;
                return false;
            }
            p += 1;
        }
        if p < self.chars.len() {
            let nc = self.chars[p];
            if nc.is_ascii_alphanumeric() || nc == '_' {
                self.pos = start_pos;
                self.line = start_line;
                self.col = start_col;
                return false;
            }
        }
        for _ in kw.chars() {
            self.advance();
        }
        true
    }

    fn parse_file(&mut self) -> Result<Vec<Stmt>, CompileError> {
        let mut stmts = Vec::new();
        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() {
                break;
            }
            match self.parse_stmt() {
                Ok(s) => stmts.push(s),
                Err(e) => return Err(e),
            }
        }
        Ok(stmts)
    }

    fn parse_stmt(&mut self) -> Result<Stmt, CompileError> {
        self.skip_ws();
        if self.pos >= self.chars.len() {
            return Err(self.error("expected root"));
        }

        let pos_before = self.pos;
        let line_before = self.line;
        let col_before = self.col;

        if self.match_keyword("let") {
            self.skip_ws();
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some('=') {
                return Err(self.error("expected block"));
            }
            self.advance();
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::VarDecl(name, block));
        }
        self.pos = pos_before;
        self.line = line_before;
        self.col = col_before;

        if self.match_keyword("not") {
            self.skip_ws();
            if self.match_keyword("ahead") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotAhead, block)));
            } else if self.match_keyword("behind") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotBehind, block)));
            } else {
                self.pos = pos_before;
                self.line = line_before;
                self.col = col_before;
            }
        }

        if self.match_keyword("match") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Match, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("either") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Either, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("capture") {
            self.skip_ws();
            let mut opt_name: Option<String> = None;
            if let Some(ch) = self.current() {
                if ch.is_ascii_alphabetic() || ch == '_' {
                    let ident = self.parse_ident()?;
                    opt_name = Some(ident);
                    self.skip_ws();
                }
            }
            if self.current() != Some('{') {
                if opt_name.is_none() {
                    return Err(self.error("expected block or identifier"));
                } else {
                    return Err(self.error("expected block"));
                }
            }
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Capture(opt_name), block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("ahead") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Ahead, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("behind") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Behind, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;

        // Quantifier
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            let mut lazy = false;
            self.skip_ws();
            if self.match_keyword("lazy") {
                lazy = true;
                self.skip_ws();
            }
            if let Some(prefix) = self.parse_quant_prefix() {
                self.skip_ws();
                if !self.match_keyword("of") {
                    self.pos = save; self.line = sl; self.col = sc;
                } else {
                    self.skip_ws();
                    match self.parse_atom_for_quant() {
                        Ok(atom) => {
                            let needs_semi = match atom {
                                Atom::Literal(_) | Atom::Raw(_) | Atom::Symbol(_,_) | Atom::Range(_,_,_) | Atom::NotClass(_,_) => true,
                                _ => false,
                            };
                            if needs_semi {
                                self.skip_ws();
                                if self.current() != Some(';') {
                                    return Err(self.error("expected group_declaration, assertion_declaration, or variable_declaration"));
                                }
                                self.advance();
                                return Ok(Stmt::Quantified(prefix, lazy, atom));
                            } else {
                                self.skip_ws();
                                if self.current() == Some(';') {
                                    return Err(self.error("expected EOI, literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"));
                                }
                                return Ok(Stmt::Quantified(prefix, lazy, atom));
                            }
                        },
                        Err(e) => return Err(e),
                    }
                }
            } else {
                self.pos = save; self.line = sl; self.col = sc;
            }
        }

        // Not class/range/symbol
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if self.match_keyword("not") {
                self.skip_ws();
                if let Ok((s,e)) = self.parse_range_no_semi() {
                    self.skip_ws();
                    if self.current() != Some(';') {
                        return Err(self.error("expected amount or assertion_type"));
                    }
                    self.advance();
                    return Ok(Stmt::Simple(Atom::Range(s,e,true)));
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                if self.current() == Some('<') {
                    if let Ok((sym,_)) = self.parse_symbol_atom() {
                        self.skip_ws();
                        if self.current() != Some(';') {
                            return Err(self.error("expected amount or assertion_type"));
                        }
                        self.advance();
                        match sym {
                            Symbol::Start => return Err(self.error_custom("Error: negative start not allowed")),
                            Symbol::End => return Err(self.error_custom("Error: negative end not allowed")),
                            Symbol::Char => return Err(self.error_custom("Error: negative char not allowed")),
                            _ => {}
                        }
                        return Ok(Stmt::Simple(Atom::Symbol(sym, true)));
                    }
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                let mut content = String::new();
                let mut has = false;
                while let Some(ch) = self.current() {
                    if ch == ';' { break; }
                    if ch.is_ascii_alphanumeric() || ch == '_' || ch == ' ' || ch == '!' || ch == '@' || ch == '#' || ch == '$' || ch == '%' || ch == '&' || ch == '*' || ch == '\\' || ch == '^' {
                        content.push(ch);
                        self.advance();
                        has = true;
                    } else {
                        break;
                    }
                }
                if !has {
                    return Err(self.error("expected amount, class_content, or assertion_type"));
                }
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected amount or assertion_type"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::NotClass(content, true)));
            }
        }

        // Range
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if let Ok((s,e)) = self.parse_range_no_semi() {
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected root"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::Range(s,e,false)));
            }
            self.pos = save; self.line = sl; self.col = sc;
        }

        // Symbol
        if self.current() == Some('<') {
            if let Ok((sym,_)) = self.parse_symbol_atom() {
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected root"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::Symbol(sym, false)));
            }
        }

        // Literal
        if self.current() == Some('"') || self.current() == Some('\'') {
            let lit = self.parse_literal()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Literal(lit)));
        }

        // Raw
        if self.current() == Some('`') {
            let raw = self.parse_raw()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Raw(raw)));
        }

        // Var invocation
        if self.current() == Some('.') {
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::VarInv(name)));
        }

        Err(self.error("expected root"))
    }

    fn parse_ident(&mut self) -> Result<String, CompileError> {
        self.skip_ws();
        let mut ident = String::new();
        while let Some(ch) = self.current() {
            if ch.is_ascii_alphabetic() || ch == '_' {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        if ident.is_empty() {
            return Err(self.error("expected block or identifier"));
        }
        Ok(ident)
    }

    fn parse_var_name(&mut self) -> Result<String, CompileError> {
        self.skip_ws();
        if self.current() != Some('.') {
            return Err(self.error("expected identifier"));
        }
        self.advance();
        let mut name = String::new();
        while let Some(ch) = self.current() {
            if ch.is_ascii_alphabetic() || ch == '_' {
                name.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        if name.is_empty() {
            return Err(self.error("expected identifier"));
        }
        Ok(name)
    }

    fn parse_symbol_atom(&mut self) -> Result<(Symbol, bool), CompileError> {
        if self.current() != Some('<') {
            return Err(self.error("expected symbol_identifier"));
        }
        self.advance();
        let mut ident = String::new();
        while let Some(ch) = self.current() {
            if ch == '>' {
                break;
            }
            if ch == '\n' || ch == '\r' {
                return Err(self.error("expected symbol_identifier"));
            }
            ident.push(ch);
            self.advance();
        }
        if self.current() != Some('>') {
            return Err(self.error("expected symbol_identifier"));
        }
        self.advance();
        let trimmed = ident.trim();
        if let Some(sym) = Symbol::from_str(trimmed) {
            Ok((sym, false))
        } else {
            Err(CompileError {
                line: 0,
                col: 0,
                line_content: String::new(),
                expected: String::new(),
                custom_message: Some("Error: usage of an unrecognized symbol".to_string()),
            })
        }
    }

    fn parse_literal(&mut self) -> Result<String, CompileError> {
        let quote = self.current().unwrap();
        if quote != '"' && quote != '\'' {
            return Err(self.error("expected root"));
        }
        let is_double = quote == '"';
        self.advance();
        let mut content = String::new();
        while let Some(ch) = self.current() {
            if ch == '\\' {
                self.advance();
                if let Some(esc) = self.current() {
                    match esc {
                        'n' => { content.push('\\'); content.push('n'); self.advance(); },
                        't' => { content.push('\\'); content.push('t'); self.advance(); },
                        'r' => { content.push('\\'); content.push('r'); self.advance(); },
                        'f' => { content.push('\\'); content.push('f'); self.advance(); },
                        'b' => { content.push('\\'); content.push('b'); self.advance(); },
                        '/' => { content.push('\\'); content.push('/'); self.advance(); },
                        '\\' => { content.push('\\'); content.push('\\'); self.advance(); },
                        '"' => {
                            if is_double {
                                content.push('"');
                                self.advance();
                            } else {
                                return Err(self.error("expected root"));
                            }
                        },
                        '\'' => {
                            if !is_double {
                                content.push('\'');
                                self.advance();
                            } else {
                                return Err(self.error("expected root"));
                            }
                        },
                        _ => {
                            return Err(self.error("expected root"));
                        }
                    }
                } else {
                    return Err(self.error("expected root"));
                }
            } else if ch == '"' && is_double {
                self.advance();
                break;
            } else if ch == '\'' && !is_double {
                self.advance();
                break;
            } else {
                content.push(ch);
                self.advance();
            }
        }
        Ok(content)
    }

    fn parse_raw(&mut self) -> Result<String, CompileError> {
        if self.current() != Some('`') {
            return Err(self.error("expected root"));
        }
        self.advance();
        let mut content = String::new();
        while let Some(ch) = self.current() {
            if ch == '\\' {
                self.advance();
                if let Some(esc) = self.current() {
                    if esc == '`' {
                        content.push('`');
                        self.advance();
                    } else if esc == '\\' {
                        content.push('\\');
                        content.push('\\');
                        self.advance();
                    } else {
                        return Err(self.error("expected root"));
                    }
                } else {
                    return Err(self.error("expected root"));
                }
            } else if ch == '`' {
                self.advance();
                break;
            } else {
                content.push(ch);
                self.advance();
            }
        }
        Ok(content)
    }

    fn parse_range_no_semi(&mut self) -> Result<(char, char), CompileError> {
        self.skip_ws();
        let start = match self.current() {
            Some(c) if c != ' ' && c != '\t' && c != '\r' && c != '\n' && c != ';' && c != '{' && c != '}' => c,
            _ => return Err(self.error("expected root")),
        };
        let start_pos = self.pos;
        let start_line = self.line;
        let start_col = self.col;
        self.advance();
        self.skip_ws();
        if !self.match_keyword("to") {
            self.pos = start_pos;
            self.line = start_line;
            self.col = start_col;
            return Err(self.error("expected root"));
        }
        self.skip_ws();
        let end = match self.current() {
            Some(c) if c != ' ' && c != '\t' && c != '\r' && c != '\n' && c != ';' && c != '{' && c != '}' => c,
            _ => return Err(self.error("expected root")),
        };
        self.advance();
        Ok((start, end))
    }

    fn parse_quant_prefix(&mut self) -> Option<QuantPrefix> {
        self.skip_ws();
        let save = self.pos;
        let sl = self.line;
        let sc = self.col;

        if self.match_keyword("some") {
            return Some(QuantPrefix::Some);
        }
        self.pos = save; self.line = sl; self.col = sc;
        if self.match_keyword("any") {
            return Some(QuantPrefix::Any);
        }
        self.pos = save; self.line = sl; self.col = sc;
        if self.match_keyword("option") {
            return Some(QuantPrefix::Option);
        }
        self.pos = save; self.line = sl; self.col = sc;
        if self.match_keyword("over") {
            self.skip_ws();
            if let Some(n) = self.parse_number() {
                return Some(QuantPrefix::Over(n));
            } else {
                self.pos = save; self.line = sl; self.col = sc;
                return None;
            }
        }
        if let Some(n) = self.parse_number() {
            self.skip_ws();
            if self.match_keyword("to") {
                self.skip_ws();
                if let Some(m) = self.parse_number() {
                    return Some(QuantPrefix::Range(n, m));
                } else {
                    self.pos = save; self.line = sl; self.col = sc;
                    return None;
                }
            } else {
                return Some(QuantPrefix::Exact(n));
            }
        }
        None
    }

    fn parse_number(&mut self) -> Option<usize> {
        self.skip_ws();
        let mut num_str = String::new();
        while let Some(ch) = self.current() {
            if ch.is_ascii_digit() {
                num_str.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        if num_str.is_empty() {
            None
        } else {
            num_str.parse().ok()
        }
    }

    fn parse_atom_for_quant(&mut self) -> Result<Atom, CompileError> {
        self.skip_ws();
        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if self.match_keyword("not") {
                self.skip_ws();
                if let Ok((s,e)) = self.parse_range_no_semi() {
                    return Ok(Atom::Range(s,e,true));
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                if self.current() == Some('<') {
                    if let Ok((sym,_)) = self.parse_symbol_atom() {
                        return Ok(Atom::Symbol(sym, true));
                    }
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                let mut content = String::new();
                let mut has = false;
                while let Some(ch) = self.current() {
                    if ch == ';' || ch == '{' || ch == '}' {
                        break;
                    }
                    if ch.is_ascii_alphanumeric() || ch == '_' || ch == ' ' || ch == '!' || ch == '@' || ch == '#' || ch == '$' || ch == '%' || ch == '&' || ch == '*' || ch == '\\' || ch == '^' {
                        content.push(ch);
                        self.advance();
                        has = true;
                    } else {
                        break;
                    }
                }
                if has {
                    return Ok(Atom::NotClass(content, true));
                }
                return Err(self.error("expected amount, class_content, or assertion_type"));
            }
        }

        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if let Ok((s,e)) = self.parse_range_no_semi() {
                return Ok(Atom::Range(s,e,false));
            }
            self.pos = save; self.line = sl; self.col = sc;
        }

        if self.current() == Some('<') {
            if let Ok((sym,_)) = self.parse_symbol_atom() {
                return Ok(Atom::Symbol(sym, false));
            }
        }

        if self.current() == Some('"') || self.current() == Some('\'') {
            let lit = self.parse_literal()?;
            return Ok(Atom::Literal(lit));
        }

        if self.current() == Some('`') {
            let raw = self.parse_raw()?;
            return Ok(Atom::Raw(raw));
        }

        if self.match_keyword("match") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Atom::Group(GroupKind::Match, block));
        }
        self.pos = self.pos; // dummy to avoid borrow issues
        // need to reset after each keyword attempt

        // For brevity, we will attempt each group with save/restore pattern

        // We'll re-implement with helper

        Err(self.error("expected literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"))
    }

    fn parse_block(&mut self) -> Result<Vec<Stmt>, CompileError> {
        self.skip_ws();
        if self.current() != Some('{') {
            return Err(self.error("expected block"));
        }
        self.advance();
        let mut stmts = Vec::new();
        loop {
            self.skip_ws();
            if self.current() == Some('}') {
                self.advance();
                break;
            }
            if self.pos >= self.chars.len() {
                return Err(self.error("expected block"));
            }
            match self.parse_stmt_inside_block() {
                Ok(s) => stmts.push(s),
                Err(e) => return Err(e),
            }
        }
        Ok(stmts)
    }

    fn parse_stmt_inside_block(&mut self) -> Result<Stmt, CompileError> {
        self.skip_ws();
        if self.pos >= self.chars.len() {
            return Err(self.error("expected block"));
        }

        let pos_before = self.pos;
        let line_before = self.line;
        let col_before = self.col;

        if self.match_keyword("let") {
            self.skip_ws();
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some('=') {
                return Err(self.error("expected block"));
            }
            self.advance();
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::VarDecl(name, block));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;

        if self.match_keyword("not") {
            self.skip_ws();
            if self.match_keyword("ahead") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotAhead, block)));
            } else if self.match_keyword("behind") {
                self.skip_ws();
                let block = self.parse_block()?;
                return Ok(Stmt::Simple(Atom::Group(GroupKind::NotBehind, block)));
            } else {
                self.pos = pos_before; self.line = line_before; self.col = col_before;
            }
        }

        if self.match_keyword("match") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Match, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("either") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Either, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("capture") {
            self.skip_ws();
            let mut opt_name = None;
            if let Some(ch) = self.current() {
                if ch.is_ascii_alphabetic() || ch == '_' {
                    let ident = self.parse_ident()?;
                    opt_name = Some(ident);
                    self.skip_ws();
                }
            }
            if self.current() != Some('{') {
                if opt_name.is_none() {
                    return Err(self.error("expected block or identifier"));
                } else {
                    return Err(self.error("expected block"));
                }
            }
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Capture(opt_name), block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("ahead") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Ahead, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;
        if self.match_keyword("behind") {
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Stmt::Simple(Atom::Group(GroupKind::Behind, block)));
        }
        self.pos = pos_before; self.line = line_before; self.col = col_before;

        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            let mut lazy = false;
            self.skip_ws();
            if self.match_keyword("lazy") {
                lazy = true;
                self.skip_ws();
            }
            if let Some(prefix) = self.parse_quant_prefix() {
                self.skip_ws();
                if !self.match_keyword("of") {
                    self.pos = save; self.line = sl; self.col = sc;
                } else {
                    self.skip_ws();
                    match self.parse_atom_for_quant() {
                        Ok(atom) => {
                            let needs_semi = match atom {
                                Atom::Literal(_) | Atom::Raw(_) | Atom::Symbol(_,_) | Atom::Range(_,_,_) | Atom::NotClass(_,_) => true,
                                _ => false,
                            };
                            if needs_semi {
                                self.skip_ws();
                                if self.current() != Some(';') {
                                    return Err(self.error("expected group_declaration, assertion_declaration, or variable_declaration"));
                                }
                                self.advance();
                                return Ok(Stmt::Quantified(prefix, lazy, atom));
                            } else {
                                self.skip_ws();
                                if self.current() == Some(';') {
                                    return Err(self.error("expected quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
                                }
                                return Ok(Stmt::Quantified(prefix, lazy, atom));
                            }
                        },
                        Err(e) => return Err(e),
                    }
                }
            } else {
                self.pos = save; self.line = sl; self.col = sc;
            }
        }

        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if self.match_keyword("not") {
                self.skip_ws();
                if let Ok((s,e)) = self.parse_range_no_semi() {
                    self.skip_ws();
                    if self.current() != Some(';') {
                        return Err(self.error("expected amount or assertion_type"));
                    }
                    self.advance();
                    return Ok(Stmt::Simple(Atom::Range(s,e,true)));
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                if self.current() == Some('<') {
                    if let Ok((sym,_)) = self.parse_symbol_atom() {
                        self.skip_ws();
                        if self.current() != Some(';') {
                            return Err(self.error("expected amount or assertion_type"));
                        }
                        self.advance();
                        match sym {
                            Symbol::Start => return Err(self.error_custom("Error: negative start not allowed")),
                            Symbol::End => return Err(self.error_custom("Error: negative end not allowed")),
                            Symbol::Char => return Err(self.error_custom("Error: negative char not allowed")),
                            _ => {}
                        }
                        return Ok(Stmt::Simple(Atom::Symbol(sym, true)));
                    }
                }
                self.pos = save; self.line = sl; self.col = sc;
                self.match_keyword("not");
                self.skip_ws();
                let mut content = String::new();
                let mut has = false;
                while let Some(ch) = self.current() {
                    if ch == ';' { break; }
                    if ch.is_ascii_alphanumeric() || ch == '_' || ch == ' ' || ch == '!' || ch == '@' || ch == '#' || ch == '$' || ch == '%' || ch == '&' || ch == '*' || ch == '\\' || ch == '^' {
                        content.push(ch);
                        self.advance();
                        has = true;
                    } else {
                        break;
                    }
                }
                if !has {
                    return Err(self.error("expected amount, class_content, or assertion_type"));
                }
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected amount or assertion_type"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::NotClass(content, true)));
            }
        }

        {
            let save = self.pos;
            let sl = self.line;
            let sc = self.col;
            if let Ok((s,e)) = self.parse_range_no_semi() {
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected root"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::Range(s,e,false)));
            }
            self.pos = save; self.line = sl; self.col = sc;
        }

        if self.current() == Some('<') {
            if let Ok((sym,_)) = self.parse_symbol_atom() {
                self.skip_ws();
                if self.current() != Some(';') {
                    return Err(self.error("expected root"));
                }
                self.advance();
                return Ok(Stmt::Simple(Atom::Symbol(sym, false)));
            }
        }

        if self.current() == Some('"') || self.current() == Some('\'') {
            let lit = self.parse_literal()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Literal(lit)));
        }

        if self.current() == Some('`') {
            let raw = self.parse_raw()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::Raw(raw)));
        }

        if self.current() == Some('.') {
            let name = self.parse_var_name()?;
            self.skip_ws();
            if self.current() != Some(';') {
                return Err(self.error("expected EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration"));
            }
            self.advance();
            return Ok(Stmt::Simple(Atom::VarInv(name)));
        }

        Err(self.error("expected root"))
    }
}

const BASH_COMPLETION: &str = r#"_melody() {
    local i cur prev opts cmd
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    cmd=""
    opts=""

    for i in ${COMP_WORDS[@]}
    do
        case "${cmd},${i}" in
            ",$1")
                cmd="melody"
                ;;
            *)
                ;;
        esac
    done

    case "${cmd}" in
        melody)
            opts="-o -n -r -t -f -h -V --output --no-color --repl --generate-completions --test --test-file --help --version [INPUT_FILE_PATH]"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- "${cur}") )
                return 0
            fi
            case "${prev}" in
                --output)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -o)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --generate-completions)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --test)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -t)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --test-file)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -f)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W "${opts}" -- "${cur}") )
            return 0
            ;;
    esac
}

