fn repl_impl(no_color: bool) {
    use std::io::{self, Write};

    let use_color = !no_color && std::io::stdout().is_terminal();

    if use_color {
        println!("\x1b[92mMelody REPL v0.20.0\x1b[0m");
        println!();
        println!("\x1b[92mCommands:\x1b[0m");
        println!();
        println!("- \x1b[94m:u, :undo\x1b[0m - \x1b[92mundo the latest line\x1b[0m");
        println!("- \x1b[94m:r, :redo\x1b[0m - \x1b[92mredo the latest undo\x1b[0m");
        println!("- \x1b[94m:c, :clear\x1b[0m - \x1b[92mclear all REPL history and previous input\x1b[0m");
        println!("- \x1b[94m:s, :source\x1b[0m - \x1b[92mprint all previously entered lines\x1b[0m");
        println!("- \x1b[94m:e, :exit\x1b[0m - \x1b[92mexit the REPL\x1b[0m");
        println!();
    } else {
        println!("Melody REPL v0.20.0");
        println!();
        println!("Commands:");
        println!();
        println!("- :u, :undo - undo the latest line");
        println!("- :r, :redo - redo the latest undo");
        println!("- :c, :clear - clear all REPL history and previous input");
        println!("- :s, :source - print all previously entered lines");
        println!("- :e, :exit - exit the REPL");
        println!();
    }

    let mut history: Vec<String> = Vec::new();
    let mut redo_stack: Vec<String> = Vec::new();

    loop {
        if use_color {
            print!("\x1b[94m~ \x1b[0m");
        } else {
            print!("~ ");
        }
        io::stdout().flush().unwrap();

        let mut input = String::new();
        if io::stdin().read_line(&mut input).unwrap() == 0 {
            break;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }

        match trimmed {
            ":u" | ":undo" => {
                if history.is_empty() {
                    if use_color {
                        println!("\x1b[91mnothing to undo\r\n\x1b[0m");
                    } else {
                        println!("nothing to undo\r\n");
                    }
                    println!();
                    continue;
                }
                let last = history.pop().unwrap();
                redo_stack.push(last);
                let combined = history.join("\n");
                let compiled = if combined.trim().is_empty() {
                    String::new()
                } else {
                    match compile_melody(&combined, no_color) {
                        Ok(c) => c,
                        Err(_) => String::new(),
                    }
                };
                if use_color {
                    println!("\x1b[92mundo\x1b[0m");
                    if compiled.is_empty() {
                        println!("\x1b[94m\x1b[0m");
                    } else {
                        println!("\x1b[94m{}\x1b[0m", compiled);
                    }
                } else {
                    println!("undo");
                    println!("{}", compiled);
                }
                println!();
                continue;
            },
            ":r" | ":redo" => {
                if redo_stack.is_empty() {
                    if use_color {
                        println!("\x1b[91mnothing to redo\r\n\x1b[0m");
                    } else {
                        println!("nothing to redo\r\n");
                    }
                    println!();
                    continue;
                }
                let next = redo_stack.pop().unwrap();
                history.push(next);
                let combined = history.join("\n");
                let compiled = match compile_melody(&combined, no_color) {
                    Ok(c) => c,
                    Err(_) => String::new(),
                };
                if use_color {
                    println!("\x1b[92mredo\x1b[0m");
                    println!("\x1b[94m{}\x1b[0m", compiled);
                } else {
                    println!("redo");
                    println!("{}", compiled);
                }
                println!();
                continue;
            },
            ":c" | ":clear" => {
                history.clear();
                redo_stack.clear();
                if use_color {
                    println!("\x1b[92mclear\x1b[0m");
                } else {
                    println!("clear");
                }
                println!();
                continue;
            },
            ":s" | ":source" => {
                if history.is_empty() {
                    if use_color {
                        println!("\x1b[91mno lines to print\r\n\x1b[0m");
                    } else {
                        println!("no lines to print\r\n");
                    }
                } else {
                    if use_color {
                        println!("\x1b[92msource\x1b[0m");
                    } else {
                        println!("source");
                    }
                    for (i, line) in history.iter().enumerate() {
                        if use_color {
                            println!("\x1b[2m{}\x1b[0m \x1b[94m{}\x1b[0m", i+1, line.trim());
                        } else {
                            println!("{} {}", i+1, line.trim());
                        }
                    }
                }
                println!();
                continue;
            },
            ":e" | ":exit" => {
                if use_color {
                    println!("\x1b[92mexit\x1b[0m");
                } else {
                    println!("exit");
                }
                break;
            },
            _ => {}
        }

        let mut test_history = history.clone();
        test_history.push(input.clone());
        let combined = test_history.join("\n");

        match compile_melody(&combined, no_color) {
            Ok(compiled) => {
                history.push(input.clone());
                redo_stack.clear();
                if use_color {
                    println!("\x1b[94m{}\x1b[0m", compiled);
                } else {
                    println!("{}", compiled);
                }
                println!();
            },
            Err(e) => {
                if let Some(msg) = e.custom_message {
                    if use_color {
                        println!("\x1b[91m{}\x1b[0m", msg);
                    } else {
                        println!("{}", msg);
                    }
                } else {
                    if use_color {
                        eprintln!("\x1b[91mError:  --> {}:{}\x1b[0m", e.line, e.col);
                        eprintln!("  |");
                        eprintln!("{} | {}", e.line, e.line_content);
                        eprintln!("  | {}^---", " ".repeat(e.col.saturating_sub(1)));
                        eprintln!("  |");
                        eprintln!("  = {}", e.expected);
                    } else {
                        eprintln!("Error:  --> {}:{}", e.line, e.col);
                        eprintln!("  |");
                        eprintln!("{} | {}", e.line, e.line_content);
                        eprintln!("  | {}^---", " ".repeat(e.col.saturating_sub(1)));
                        eprintln!("  |");
                        eprintln!("  = {}", e.expected);
                    }
                }
                println!();
            }
        }
    }
}
RS
