        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }

        match trimmed {
            ":u" | ":undo" => {
                if history.is_empty() {
                    if use_color {
                        println!("\x1b[91mnothing to undo\x1b[0m");
