import pty, os, subprocess, time, fcntl

def read_all(fd):
    data=b""
    while True:
        try:
            c=os.read(fd, 4096)
            if not c:
                break
            data+=c
        except BlockingIOError:
            break
        except OSError:
            break
    return data

def repl_test(args, commands):
