import pty, os, subprocess, time, fcntl

def read_all(fd):
    data=b""
    while True:
        try:
            c=os.read(fd, 4096)
            if not c:
                break
            data+=c
        except BlockingIOError:
            break
        except OSError:
            break
    return data

def repl_test(bin_path, args, commands):
    master, slave = pty.openpty()
    proc = subprocess.Popen([bin_path]+args, stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    time.sleep(0.5)
    fl = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, fl | os.O_NONBLOCK)
    out = read_all(master).decode(errors='ignore')
    for cmd in commands:
        os.write(master, (cmd+"\n").encode())
        time.sleep(0.4)
        out = read_all(master).decode(errors='ignore')
        print(f"After {cmd!r}: {repr(out)}")
    os.write(master, b":e\n")
    time.sleep(0.3)
    proc.terminate()
    os.close(master)

print("=== our ===")
